import * as THREE from 'three';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { KTX2Exporter } from 'three/addons/exporters/KTX2Exporter.js';
import { HDRLoader } from 'three/addons/loaders/HDRLoader.js';
import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

let scene, camera, renderer, exporter, mesh, controls, environment, renderTarget, dataTexture;

const params = {
	target: 'render-target',
	export: exportFile
};

init();

function init() {

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.toneMapping = THREE.AgXToneMapping;
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	//

	camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 0.1, 100 );
	camera.position.set( 10, 0, 0 );

	scene = new THREE.Scene();

	exporter = new KTX2Exporter();
	const hdrLoader = new HDRLoader();

	//

	renderTarget = new THREE.WebGLRenderTarget( 1024, 512, { type: THREE.HalfFloatType } );

	hdrLoader.load( 'textures/equirectangular/venice_sunset_1k.hdr', function ( texture ) {

		texture.mapping = THREE.EquirectangularReflectionMapping;

		environment = texture;
		scene.background = environment;

	} );

	createDataTexture();

	//

	controls = new OrbitControls( camera, renderer.domElement );
	controls.enableDamping = true;
	controls.rotateSpeed = - 0.25; // negative, to track mouse pointer

	//

	window.addEventListener( 'resize', onWindowResize );

	const gui = new GUI();

	gui.add( params, 'target' ).options( [ 'render-target', 'data-texture' ] ).onChange( swapScene );
	gui.add( params, 'export' ).name( 'Export KTX2' );
	gui.open();

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	controls.update();
	renderer.render( scene, camera );

}

function createDataTexture() {

	const normal = new THREE.Vector3();
	const coord = new THREE.Vector2();
	const size = 800, radius = 320, factor = Math.PI * 0.5 / radius;
	const data = new Float32Array( 4 * size * size );

	for ( let i = 0; i < size; i ++ ) {

		for ( let j = 0; j < size; j ++ ) {

			const idx = i * size * 4 + j * 4;
			coord.set( j, i ).subScalar( size / 2 );

			if ( coord.length() < radius )
				normal.set(
					Math.sin( coord.x * factor ),
					Math.sin( coord.y * factor ),
					Math.cos( coord.x * factor )
				);
			else
				normal.set( 0, 0, 1 );

			data[ idx + 0 ] = .5 + .5 * normal.x;
			data[ idx + 1 ] = .5 + .5 * normal.y;
			data[ idx + 2 ] = .5 + .5 * normal.z;
			data[ idx + 3 ] = 1.;

		}

	}

	dataTexture = new THREE.DataTexture( data, size, size, THREE.RGBAFormat, THREE.FloatType );
	dataTexture.needsUpdate = true;

	const material = new THREE.MeshBasicMaterial( { map: dataTexture } );
	const quad = new THREE.PlaneGeometry( 50, 50 );
	mesh = new THREE.Mesh( quad, material );
	mesh.visible = false;

	scene.add( mesh );

}

function swapScene() {

	if ( params.target == 'render-target' ) {

		camera.position.set( 10, 0, 0 );
		controls.enabled = true;
		scene.background = environment;
		mesh.visible = false;
		renderer.toneMapping = THREE.AgXToneMapping;

	} else {

		camera.position.set( 0, 0, 70 );
		controls.enabled = false;
		scene.background = new THREE.Color( 0, 0, 0 );
		mesh.visible = true;
		renderer.toneMapping = THREE.NoToneMapping;

	}

}

async function exportFile() {

	let result;

	if ( params.target == 'render-target' ) {

		const exportCamera = camera.clone();
		exportCamera.aspect = renderTarget.width / renderTarget.height;
		exportCamera.updateProjectionMatrix();

		renderer.setRenderTarget( renderTarget );
		renderer.render( scene, exportCamera );
		renderer.setRenderTarget( null );

		result = await exporter.parse( renderer, renderTarget );

	} else {

		result = await exporter.parse( dataTexture );

	}

	saveArrayBuffer( result, params.target + '.ktx2' );

}

function saveArrayBuffer( buffer, filename ) {

	const blob = new Blob( [ buffer ], { type: 'image/ktx2' } );
	const link = document.createElement( 'a' );

	link.href = URL.createObjectURL( blob );
	link.download = filename;
	link.click();

}

import * as THREE from 'three';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { OBJExporter } from 'three/addons/exporters/OBJExporter.js';
import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

let camera, scene, renderer;

const params = {
	addTriangle: addTriangle,
	addCube: addCube,
	addCylinder: addCylinder,
	addMultiple: addMultiple,
	addTransformed: addTransformed,
	addPoints: addPoints,
	exportToObj: exportToObj
};

init();

function init() {

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	camera = new THREE.PerspectiveCamera( 70, window.innerWidth / window.innerHeight, 1, 1000 );
	camera.position.set( 0, 0, 400 );

	scene = new THREE.Scene();

	const ambientLight = new THREE.AmbientLight( 0xffffff );
	scene.add( ambientLight );

	const directionalLight = new THREE.DirectionalLight( 0xffffff, 2.5 );
	directionalLight.position.set( 0, 1, 1 );
	scene.add( directionalLight );

	const gui = new GUI();

	let h = gui.addFolder( 'Geometry Selection' );
	h.add( params, 'addTriangle' ).name( 'Triangle' );
	h.add( params, 'addCube' ).name( 'Cube' );
	h.add( params, 'addCylinder' ).name( 'Cylinder' );
	h.add( params, 'addMultiple' ).name( 'Multiple objects' );
	h.add( params, 'addTransformed' ).name( 'Transformed objects' );
	h.add( params, 'addPoints' ).name( 'Point Cloud' );

	h = gui.addFolder( 'Export' );
	h.add( params, 'exportToObj' ).name( 'Export OBJ' );

	gui.open();

	addGeometry( 1 );

	window.addEventListener( 'resize', onWindowResize );

	const controls = new OrbitControls( camera, renderer.domElement );
	controls.enablePan = false;

}

function exportToObj() {

	const exporter = new OBJExporter();
	const result = exporter.parse( scene );
	saveString( result, 'object.obj' );

}

function addGeometry( type ) {

	for ( let i = 0; i < scene.children.length; i ++ ) {

		const child = scene.children[ i ];

		if ( child.isMesh || child.isPoints ) {

			child.geometry.dispose();
			scene.remove( child );
			i --;

		}

	}

	if ( type === 1 ) {

		const material = new THREE.MeshLambertMaterial( { color: 0x00cc00 } );
		const geometry = generateTriangleGeometry();

		scene.add( new THREE.Mesh( geometry, material ) );


	} else if ( type === 2 ) {

		const material = new THREE.MeshLambertMaterial( { color: 0x00cc00 } );
		const geometry = new THREE.BoxGeometry( 100, 100, 100 );
		scene.add( new THREE.Mesh( geometry, material ) );

	} else if ( type === 3 ) {

		const material = new THREE.MeshLambertMaterial( { color: 0x00cc00 } );
		const geometry = new THREE.CylinderGeometry( 50, 50, 100, 30, 1 );
		scene.add( new THREE.Mesh( geometry, material ) );

	} else if ( type === 4 || type === 5 ) {

		const material = new THREE.MeshLambertMaterial( { color: 0x00cc00 } );
		const geometry = generateTriangleGeometry();

		const mesh = new THREE.Mesh( geometry, material );
		mesh.position.x = - 200;
		scene.add( mesh );

		const geometry2 = new THREE.BoxGeometry( 100, 100, 100 );
		const mesh2 = new THREE.Mesh( geometry2, material );
		scene.add( mesh2 );

		const geometry3 = new THREE.CylinderGeometry( 50, 50, 100, 30, 1 );
		const mesh3 = new THREE.Mesh( geometry3, material );
		mesh3.position.x = 200;
		scene.add( mesh3 );

		if ( type === 5 ) {

			mesh.rotation.y = Math.PI / 4.0;
			mesh2.rotation.y = Math.PI / 4.0;
			mesh3.rotation.y = Math.PI / 4.0;

		}

	} else if ( type === 6 ) {

		const points = [ 0, 0, 0, 100, 0, 0, 100, 100, 0, 0, 100, 0 ];
		const colors = [ 0.5, 0, 0, 0.5, 0, 0, 0, 0.5, 0, 0, 0.5, 0 ];

		const geometry = new THREE.BufferGeometry();
		geometry.setAttribute( 'position', new THREE.Float32BufferAttribute( points, 3 ) );
		geometry.setAttribute( 'color', new THREE.Float32BufferAttribute( colors, 3 ) );

		const material = new THREE.PointsMaterial( { size: 10, vertexColors: true } );

		const pointCloud = new THREE.Points( geometry, material );
		pointCloud.name = 'point cloud';
		scene.add( pointCloud );

	}

}

function addTriangle() {

	addGeometry( 1 );

}

function addCube() {

	addGeometry( 2 );

}

function addCylinder() {

	addGeometry( 3 );

}

function addMultiple() {

	addGeometry( 4 );

}

function addTransformed() {

	addGeometry( 5 );

}

function addPoints() {

	addGeometry( 6 );

}

