function initView( scene, name, logDepthBuf ) {

	const framecontainer = document.getElementById( 'container_' + name );

	const camera = new THREE.PerspectiveCamera( 50, screensplit * SCREEN_WIDTH / SCREEN_HEIGHT, NEAR, FAR );
	scene.add( camera );

