	new THREE.Vector3( 0, - 40, - 40 ),
	new THREE.Vector3( 0, 40, - 40 ),
	new THREE.Vector3( 0, 140, - 40 ),
	new THREE.Vector3( 0, 40, 40 ),
	new THREE.Vector3( 0, - 40, 40 )
] );

