function addTube() {

	if ( mesh !== undefined ) {

		parent.remove( mesh );
		mesh.geometry.dispose();

	}

	const extrudePath = splines[ params.spline ];

	tubeGeometry = new THREE.TubeGeometry( extrudePath, params.extrusionSegments, 2, params.radiusSegments, params.closed );

	addGeometry( tubeGeometry );

	setScale();

