		.absarc( 40, 40, 40, 0, Math.PI * 2, false );

	const smileyEye1Path = new THREE.Path()
		.moveTo( 35, 20 )
		.absellipse( 25, 20, 10, 10, 0, Math.PI * 2, true );

	const smileyEye2Path = new THREE.Path()
		.moveTo( 65, 20 )
		.absarc( 55, 20, 10, 0, Math.PI * 2, true );

	const smileyMouthPath = new THREE.Path()
		.moveTo( 20, 40 )
		.quadraticCurveTo( 40, 60, 60, 40 )
		.bezierCurveTo( 70, 45, 70, 50, 60, 60 )
		.quadraticCurveTo( 40, 80, 20, 60 )
		.quadraticCurveTo( 5, 50, 20, 40 );

	smileyShape.holes.push( smileyEye1Path );
	smileyShape.holes.push( smileyEye2Path );
	smileyShape.holes.push( smileyMouthPath );


	// Spline shape

	const splinepts = [];
	splinepts.push( new THREE.Vector2( 70, 20 ) );
	splinepts.push( new THREE.Vector2( 80, 90 ) );
	splinepts.push( new THREE.Vector2( - 30, 70 ) );
	splinepts.push( new THREE.Vector2( 0, 0 ) );

	const splineShape = new THREE.Shape()
		.moveTo( 0, 0 )
		.splineThru( splinepts );

	const extrudeSettings = { depth: 8, bevelEnabled: true, bevelSegments: 2, steps: 2, bevelSize: 1, bevelThickness: 1 };

	// addShape( shape, color, x, y, z, rx, ry,rz, s );

	addShape( californiaShape, extrudeSettings, 0xf08000, - 300, - 100, 0, 0, 0, 0, 1 );
	addShape( triangleShape, extrudeSettings, 0x8080f0, - 180, 0, 0, 0, 0, 0, 1 );
	addShape( roundedRectShape, extrudeSettings, 0x008000, - 150, 150, 0, 0, 0, 0, 1 );
	addShape( trackShape, extrudeSettings, 0x008080, 200, - 100, 0, 0, 0, 0, 1 );
	addShape( squareShape, extrudeSettings, 0x0040f0, 150, 100, 0, 0, 0, 0, 1 );
	addShape( heartShape, extrudeSettings, 0xf00000, 60, 100, 0, 0, 0, Math.PI, 1 );
	addShape( circleShape, extrudeSettings, 0x00f000, 120, 250, 0, 0, 0, 0, 1 );
	addShape( fishShape, extrudeSettings, 0x404040, - 60, 200, 0, 0, 0, 0, 1 );
	addShape( smileyShape, extrudeSettings, 0xf000f0, - 200, 250, 0, 0, 0, Math.PI, 1 );
	addShape( arcShape, extrudeSettings, 0x804000, 150, 0, 0, 0, 0, 0, 1 );
	addShape( splineShape, extrudeSettings, 0x808080, - 50, - 100, 0, 0, 0, 0, 1 );

	addLineShape( arcShape.holes[ 0 ], 0x804000, 150, 0, 0, 0, 0, 0, 1 );

	for ( let i = 0; i < smileyShape.holes.length; i += 1 ) {

		addLineShape( smileyShape.holes[ i ], 0xf000f0, - 200, 250, 0, 0, 0, Math.PI, 1 );

	}

	//

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	container.appendChild( renderer.domElement );

	stats = new Stats();
	container.appendChild( stats.dom );

	container.style.touchAction = 'none';
	container.addEventListener( 'pointerdown', onPointerDown );

	//

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	windowHalfX = window.innerWidth / 2;

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function onPointerDown( event ) {

	if ( event.isPrimary === false ) return;

	pointerXOnPointerDown = event.clientX - windowHalfX;
	targetRotationOnPointerDown = targetRotation;

	document.addEventListener( 'pointermove', onPointerMove );
	document.addEventListener( 'pointerup', onPointerUp );

}

function onPointerMove( event ) {

	if ( event.isPrimary === false ) return;

	pointerX = event.clientX - windowHalfX;

	targetRotation = targetRotationOnPointerDown + ( pointerX - pointerXOnPointerDown ) * 0.02;

}

function onPointerUp( event ) {

	if ( event.isPrimary === false ) return;

	document.removeEventListener( 'pointermove', onPointerMove );
	document.removeEventListener( 'pointerup', onPointerUp );

}

//

function animate() {

	render();
	stats.update();

}

function render() {

	group.rotation.y += ( targetRotation - group.rotation.y ) * 0.05;
	renderer.render( scene, camera );

}

import * as THREE from 'three';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { TransformControls } from 'three/addons/controls/TransformControls.js';

let container;
let camera, scene, renderer;
const splineHelperObjects = [];
let splinePointsLength = 4;
const positions = [];
const point = new THREE.Vector3();

const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
const onUpPosition = new THREE.Vector2();
const onDownPosition = new THREE.Vector2();

const geometry = new THREE.BoxGeometry( 20, 20, 20 );
let transformControl;

const ARC_SEGMENTS = 200;

const splines = {};

const params = {
	uniform: true,
	tension: 0.5,
	centripetal: true,
	chordal: true,
	addPoint: addPoint,
	removePoint: removePoint,
	exportSpline: exportSpline
};

init();

function init() {

	container = document.getElementById( 'container' );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xf0f0f0 );

	camera = new THREE.PerspectiveCamera( 70, window.innerWidth / window.innerHeight, 1, 10000 );
	camera.position.set( 0, 250, 1000 );
	scene.add( camera );

	scene.add( new THREE.AmbientLight( 0xf0f0f0, 3 ) );
	const light = new THREE.SpotLight( 0xffffff, 4.5 );
	light.position.set( 0, 1500, 200 );
	light.angle = Math.PI * 0.2;
	light.decay = 0;
	light.castShadow = true;
	light.shadow.camera.near = 200;
	light.shadow.camera.far = 2000;
	light.shadow.bias = - 0.000222;
	light.shadow.mapSize.width = 1024;
	light.shadow.mapSize.height = 1024;
	scene.add( light );

	const planeGeometry = new THREE.PlaneGeometry( 2000, 2000 );
	planeGeometry.rotateX( - Math.PI / 2 );
	const planeMaterial = new THREE.ShadowMaterial( { color: 0x000000, opacity: 0.2 } );

	const plane = new THREE.Mesh( planeGeometry, planeMaterial );
	plane.position.y = - 200;
	plane.receiveShadow = true;
	scene.add( plane );

	const helper = new THREE.GridHelper( 2000, 100 );
	helper.position.y = - 199;
	helper.material.opacity = 0.25;
	helper.material.transparent = true;
	scene.add( helper );

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.shadowMap.enabled = true;
	container.appendChild( renderer.domElement );

	const gui = new GUI();

	gui.add( params, 'uniform' ).onChange( render );
	gui.add( params, 'tension', 0, 1 ).step( 0.01 ).onChange( function ( value ) {

		splines.uniform.tension = value;
		updateSplineOutline();
		render();

	} );
	gui.add( params, 'centripetal' ).onChange( render );
	gui.add( params, 'chordal' ).onChange( render );
	gui.add( params, 'addPoint' );
	gui.add( params, 'removePoint' );
	gui.add( params, 'exportSpline' );
	gui.open();

	// Controls
	const controls = new OrbitControls( camera, renderer.domElement );
	controls.damping = 0.2;
	controls.addEventListener( 'change', render );

	transformControl = new TransformControls( camera, renderer.domElement );
	transformControl.addEventListener( 'change', render );
	transformControl.addEventListener( 'dragging-changed', function ( event ) {

		controls.enabled = ! event.value;

	} );
	scene.add( transformControl.getHelper() );

	transformControl.addEventListener( 'objectChange', function () {

		updateSplineOutline();

	} );

	document.addEventListener( 'pointerdown', onPointerDown );
	document.addEventListener( 'pointerup', onPointerUp );
	document.addEventListener( 'pointermove', onPointerMove );
	window.addEventListener( 'resize', onWindowResize );

	/*******
	 * Curves
	 *********/

	for ( let i = 0; i < splinePointsLength; i ++ ) {

		addSplineObject( positions[ i ] );

	}

	positions.length = 0;

	for ( let i = 0; i < splinePointsLength; i ++ ) {

		positions.push( splineHelperObjects[ i ].position );

	}

	const geometry = new THREE.BufferGeometry();
	geometry.setAttribute( 'position', new THREE.BufferAttribute( new Float32Array( ARC_SEGMENTS * 3 ), 3 ) );

	let curve = new THREE.CatmullRomCurve3( positions );
	curve.curveType = 'catmullrom';
	curve.mesh = new THREE.Line( geometry.clone(), new THREE.LineBasicMaterial( {
		color: 0xff0000,
		opacity: 0.35
	} ) );
	curve.mesh.castShadow = true;
	splines.uniform = curve;

	curve = new THREE.CatmullRomCurve3( positions );
	curve.curveType = 'centripetal';
	curve.mesh = new THREE.Line( geometry.clone(), new THREE.LineBasicMaterial( {
		color: 0x00ff00,
		opacity: 0.35
	} ) );
	curve.mesh.castShadow = true;
	splines.centripetal = curve;

	curve = new THREE.CatmullRomCurve3( positions );
	curve.curveType = 'chordal';
	curve.mesh = new THREE.Line( geometry.clone(), new THREE.LineBasicMaterial( {
		color: 0x0000ff,
		opacity: 0.35
	} ) );
	curve.mesh.castShadow = true;
	splines.chordal = curve;

	for ( const k in splines ) {

		const spline = splines[ k ];
		scene.add( spline.mesh );

	}

	load( [ new THREE.Vector3( 289.76843686945404, 452.51481137238443, 56.10018915737797 ),
		new THREE.Vector3( - 53.56300074753207, 171.49711742836848, - 14.495472686253045 ),
		new THREE.Vector3( - 91.40118730204415, 176.4306956436485, - 6.958271935582161 ),
		new THREE.Vector3( - 383.785318791128, 491.1365363371675, 47.869296953772746 ) ] );

	render();

}

function addSplineObject( position ) {

	const material = new THREE.MeshLambertMaterial( { color: Math.random() * 0xffffff } );
	const object = new THREE.Mesh( geometry, material );

	if ( position ) {

		object.position.copy( position );

	} else {

		object.position.x = Math.random() * 1000 - 500;
		object.position.y = Math.random() * 600;
		object.position.z = Math.random() * 800 - 400;

	}

	object.castShadow = true;
	object.receiveShadow = true;
	scene.add( object );
	splineHelperObjects.push( object );
	return object;

}

function addPoint() {

	splinePointsLength ++;

	positions.push( addSplineObject().position );

	updateSplineOutline();

	render();

}

function removePoint() {

	if ( splinePointsLength <= 4 ) {

		return;

	}

	const point = splineHelperObjects.pop();
	splinePointsLength --;
	positions.pop();

	if ( transformControl.object === point ) transformControl.detach();
	scene.remove( point );

	updateSplineOutline();

	render();

}

function updateSplineOutline() {

	for ( const k in splines ) {

		const spline = splines[ k ];

		const splineMesh = spline.mesh;
		const position = splineMesh.geometry.attributes.position;

		for ( let i = 0; i < ARC_SEGMENTS; i ++ ) {

			const t = i / ( ARC_SEGMENTS - 1 );
			spline.getPoint( t, point );
			position.setXYZ( i, point.x, point.y, point.z );

		}

		position.needsUpdate = true;

	}

}

function exportSpline() {

	const strplace = [];

	for ( let i = 0; i < splinePointsLength; i ++ ) {

		const p = splineHelperObjects[ i ].position;
		strplace.push( `new THREE.Vector3(${p.x}, ${p.y}, ${p.z})` );

	}

	console.log( strplace.join( ',\n' ) );
	const code = '[' + ( strplace.join( ',\n\t' ) ) + ']';
	prompt( 'copy and paste code', code );

}

function load( new_positions ) {

	while ( new_positions.length > positions.length ) {

		addPoint();

	}

	while ( new_positions.length < positions.length ) {

		removePoint();

	}

	for ( let i = 0; i < positions.length; i ++ ) {

		positions[ i ].copy( new_positions[ i ] );

	}

	updateSplineOutline();

}

function render() {

	splines.uniform.mesh.visible = params.uniform;
	splines.centripetal.mesh.visible = params.centripetal;
	splines.chordal.mesh.visible = params.chordal;
	renderer.render( scene, camera );

}

function onPointerDown( event ) {

	onDownPosition.x = event.clientX;
	onDownPosition.y = event.clientY;

}

function onPointerUp( event ) {

	onUpPosition.x = event.clientX;
	onUpPosition.y = event.clientY;

	if ( onDownPosition.distanceTo( onUpPosition ) === 0 ) {

		transformControl.detach();
		render();

	}

}

function onPointerMove( event ) {

	pointer.x = ( event.clientX / window.innerWidth ) * 2 - 1;
	pointer.y = - ( event.clientY / window.innerHeight ) * 2 + 1;

	raycaster.setFromCamera( pointer, camera );

	const intersects = raycaster.intersectObjects( splineHelperObjects, false );

	if ( intersects.length > 0 ) {

		const object = intersects[ 0 ].object;

		if ( object !== transformControl.object ) {

			transformControl.attach( object );

		}

	}

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

	render();

}

import * as THREE from 'three';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { TeapotGeometry } from 'three/addons/geometries/TeapotGeometry.js';

let camera, scene, renderer;
let cameraControls;
let effectController;
const teapotSize = 300;
let ambientLight, light;

let tess = - 1;	// force initialization
let bBottom;
let bLid;
let bBody;
let bFitLid;
let bNonBlinn;
let shading;

let teapot, textureCube;
const materials = {};

init();
render();

function init() {

	const container = document.createElement( 'div' );
	document.body.appendChild( container );

	const canvasWidth = window.innerWidth;
	const canvasHeight = window.innerHeight;

	// CAMERA
	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 1, 80000 );
	camera.position.set( - 600, 550, 1300 );

	// LIGHTS
	ambientLight = new THREE.AmbientLight( 0x7c7c7c, 2.0 );

	light = new THREE.DirectionalLight( 0xFFFFFF, 2.0 );
	light.position.set( 0.32, 0.39, 0.7 );

	// RENDERER
	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( canvasWidth, canvasHeight );
	container.appendChild( renderer.domElement );

	// EVENTS
	window.addEventListener( 'resize', onWindowResize );

	// CONTROLS
	cameraControls = new OrbitControls( camera, renderer.domElement );
	cameraControls.addEventListener( 'change', render );

	// TEXTURE MAP
	const textureMap = new THREE.TextureLoader().load( 'textures/uv_grid_opengl.jpg' );
	textureMap.wrapS = textureMap.wrapT = THREE.RepeatWrapping;
	textureMap.anisotropy = 16;
	textureMap.colorSpace = THREE.SRGBColorSpace;

	// REFLECTION MAP
	const path = 'textures/cube/pisa/';
	const urls = [ 'px.png', 'nx.png', 'py.png', 'ny.png', 'pz.png', 'nz.png' ];

	textureCube = new THREE.CubeTextureLoader().setPath( path ).load( urls );

	materials[ 'wireframe' ] = new THREE.MeshBasicMaterial( { wireframe: true } );
	materials[ 'flat' ] = new THREE.MeshPhongMaterial( { specular: 0x000000, flatShading: true, side: THREE.DoubleSide } );
	materials[ 'smooth' ] = new THREE.MeshLambertMaterial( { side: THREE.DoubleSide } );
	materials[ 'glossy' ] = new THREE.MeshPhongMaterial( { color: 0xc0c0c0, specular: 0x404040, shininess: 300, side: THREE.DoubleSide } );
	materials[ 'textured' ] = new THREE.MeshPhongMaterial( { map: textureMap, side: THREE.DoubleSide } );
	materials[ 'reflective' ] = new THREE.MeshPhongMaterial( { envMap: textureCube, side: THREE.DoubleSide } );

	// scene itself
	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xAAAAAA );

	scene.add( ambientLight );
	scene.add( light );

	// GUI
	setupGui();

}

// EVENT HANDLERS

function onWindowResize() {

	const canvasWidth = window.innerWidth;
	const canvasHeight = window.innerHeight;

	renderer.setSize( canvasWidth, canvasHeight );

	camera.aspect = canvasWidth / canvasHeight;
	camera.updateProjectionMatrix();

	render();

}

function setupGui() {

	effectController = {
		newTess: 15,
		bottom: true,
		lid: true,
		body: true,
		fitLid: false,
		nonblinn: false,
		newShading: 'glossy'
	};

	const gui = new GUI();
	gui.add( effectController, 'newTess', [ 2, 3, 4, 5, 6, 8, 10, 15, 20, 30, 40, 50 ] ).name( 'Tessellation Level' ).onChange( render );
	gui.add( effectController, 'lid' ).name( 'display lid' ).onChange( render );
	gui.add( effectController, 'body' ).name( 'display body' ).onChange( render );
	gui.add( effectController, 'bottom' ).name( 'display bottom' ).onChange( render );
	gui.add( effectController, 'fitLid' ).name( 'snug lid' ).onChange( render );
	gui.add( effectController, 'nonblinn' ).name( 'original scale' ).onChange( render );
	gui.add( effectController, 'newShading', [ 'wireframe', 'flat', 'smooth', 'glossy', 'textured', 'reflective' ] ).name( 'Shading' ).onChange( render );

}


//

function render() {

	if ( effectController.newTess !== tess ||
		effectController.bottom !== bBottom ||
		effectController.lid !== bLid ||
		effectController.body !== bBody ||
		effectController.fitLid !== bFitLid ||
		effectController.nonblinn !== bNonBlinn ||
		effectController.newShading !== shading ) {

		tess = effectController.newTess;
		bBottom = effectController.bottom;
		bLid = effectController.lid;
		bBody = effectController.body;
		bFitLid = effectController.fitLid;
		bNonBlinn = effectController.nonblinn;
		shading = effectController.newShading;

		createNewTeapot();

	}

	// skybox is rendered separately, so that it is always behind the teapot.
	if ( shading === 'reflective' ) {

		scene.background = textureCube;

	} else {

		scene.background = null;

	}

	renderer.render( scene, camera );

}

// Whenever the teapot changes, the scene is rebuilt from scratch (not much to it).
function createNewTeapot() {

	if ( teapot !== undefined ) {

		teapot.geometry.dispose();
		scene.remove( teapot );

	}

	const geometry = new TeapotGeometry( teapotSize,
		tess,
		effectController.bottom,
		effectController.lid,
		effectController.body,
		effectController.fitLid,
		! effectController.nonblinn );

	teapot = new THREE.Mesh( geometry, materials[ shading ] );

	scene.add( teapot );

}

import * as THREE from 'three';

import Stats from 'three/addons/libs/stats.module.js';

import { FirstPersonControls } from 'three/addons/controls/FirstPersonControls.js';
import { ImprovedNoise } from 'three/addons/math/ImprovedNoise.js';

let container, stats;
let camera, controls, scene, renderer;
let mesh, texture;

const worldWidth = 256, worldDepth = 256;
const timer = new THREE.Timer();
timer.connect( document );

init();

function init() {

	container = document.getElementById( 'container' );

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 1, 10000 );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xefd1b5 );
	scene.fog = new THREE.FogExp2( 0xefd1b5, 0.0025 );

	const data = generateHeight( worldWidth, worldDepth );

	camera.position.set( 100, 800, - 800 );
	camera.lookAt( - 100, 810, - 800 );

	const geometry = new THREE.PlaneGeometry( 7500, 7500, worldWidth - 1, worldDepth - 1 );
	geometry.rotateX( - Math.PI / 2 );

	const vertices = geometry.attributes.position.array;

	for ( let i = 0, j = 0, l = vertices.length; i < l; i ++, j += 3 ) {

		vertices[ j + 1 ] = data[ i ] * 10;

	}

	texture = new THREE.CanvasTexture( generateTexture( data, worldWidth, worldDepth ) );
	texture.wrapS = THREE.ClampToEdgeWrapping;
	texture.wrapT = THREE.ClampToEdgeWrapping;
	texture.colorSpace = THREE.SRGBColorSpace;

	mesh = new THREE.Mesh( geometry, new THREE.MeshBasicMaterial( { map: texture } ) );
	scene.add( mesh );

	renderer = new THREE.WebGLRenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	container.appendChild( renderer.domElement );

	controls = new FirstPersonControls( camera, renderer.domElement );
	controls.movementSpeed = 150;
	controls.lookSpeed = 0.2;

	stats = new Stats();
	container.appendChild( stats.dom );


	//

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function generateHeight( width, height ) {

	let seed = Math.PI / 4;
	window.Math.random = function () {

		const x = Math.sin( seed ++ ) * 10000;
		return x - Math.floor( x );

	};

	const size = width * height, data = new Uint8Array( size );
	const perlin = new ImprovedNoise(), z = Math.random() * 100;

	let quality = 1;

	for ( let j = 0; j < 4; j ++ ) {

		for ( let i = 0; i < size; i ++ ) {

			const x = i % width, y = ~ ~ ( i / width );
			data[ i ] += Math.abs( perlin.noise( x / quality, y / quality, z ) * quality * 1.75 );

		}

		quality *= 5;

	}

	return data;

}

function generateTexture( data, width, height ) {

	let context, image, imageData, shade;

	const vector3 = new THREE.Vector3( 0, 0, 0 );

	const sun = new THREE.Vector3( 1, 1, 1 );
	sun.normalize();

	const canvas = document.createElement( 'canvas' );
	canvas.width = width;
	canvas.height = height;

	context = canvas.getContext( '2d' );
	context.fillStyle = '#000';
	context.fillRect( 0, 0, width, height );

	image = context.getImageData( 0, 0, canvas.width, canvas.height );
	imageData = image.data;

	for ( let i = 0, j = 0, l = imageData.length; i < l; i += 4, j ++ ) {

		vector3.x = data[ j - 2 ] - data[ j + 2 ];
		vector3.y = 2;
		vector3.z = data[ j - width * 2 ] - data[ j + width * 2 ];
		vector3.normalize();

		shade = vector3.dot( sun );

		imageData[ i ] = ( 96 + shade * 128 ) * ( 0.5 + data[ j ] * 0.007 );
		imageData[ i + 1 ] = ( 32 + shade * 96 ) * ( 0.5 + data[ j ] * 0.007 );
		imageData[ i + 2 ] = ( shade * 96 ) * ( 0.5 + data[ j ] * 0.007 );

	}

	context.putImageData( image, 0, 0 );

	// Scaled 4x

	const canvasScaled = document.createElement( 'canvas' );
	canvasScaled.width = width * 4;
	canvasScaled.height = height * 4;

	context = canvasScaled.getContext( '2d' );
	context.scale( 4, 4 );
	context.drawImage( canvas, 0, 0 );

	image = context.getImageData( 0, 0, canvasScaled.width, canvasScaled.height );
	imageData = image.data;

	for ( let i = 0, l = imageData.length; i < l; i += 4 ) {

		const v = ~ ~ ( Math.random() * 5 );

		imageData[ i ] += v;
