		// positions

		const x = Math.random() * n - n2;
		const y = Math.random() * n - n2;
		const z = Math.random() * n - n2;

		const ax = x + Math.random() * d - d2;
		const ay = y + Math.random() * d - d2;
		const az = z + Math.random() * d - d2;

		const bx = x + Math.random() * d - d2;
		const by = y + Math.random() * d - d2;
		const bz = z + Math.random() * d - d2;

		const cx = x + Math.random() * d - d2;
		const cy = y + Math.random() * d - d2;
		const cz = z + Math.random() * d - d2;

		positions[ i ] = ax;
		positions[ i + 1 ] = ay;
		positions[ i + 2 ] = az;

		positions[ i + 3 ] = bx;
		positions[ i + 4 ] = by;
		positions[ i + 5 ] = bz;

		positions[ i + 6 ] = cx;
		positions[ i + 7 ] = cy;
		positions[ i + 8 ] = cz;

		// flat face normals

		pA.set( ax, ay, az );
		pB.set( bx, by, bz );
		pC.set( cx, cy, cz );

		cb.subVectors( pC, pB );
		ab.subVectors( pA, pB );
		cb.cross( ab );

		cb.normalize();

		const nx = cb.x;
		const ny = cb.y;
		const nz = cb.z;

		normals[ i ] = nx;
		normals[ i + 1 ] = ny;
		normals[ i + 2 ] = nz;

		normals[ i + 3 ] = nx;
		normals[ i + 4 ] = ny;
		normals[ i + 5 ] = nz;

		normals[ i + 6 ] = nx;
		normals[ i + 7 ] = ny;
