import * as THREE from 'three';

import Stats from 'three/addons/libs/stats.module.js';

let renderer, scene, camera, stats;
let pointclouds;
let raycaster;
let intersection = null;
let spheresIndex = 0;
let timer;
let toggle = 0;

const pointer = new THREE.Vector2();
const spheres = [];

const threshold = 0.1;
const pointSize = 0.05;
const width = 80;
const length = 160;
const rotateY = new THREE.Matrix4().makeRotationY( 0.005 );

init();

function generatePointCloudGeometry( color, width, length ) {

	const geometry = new THREE.BufferGeometry();
	const numPoints = width * length;

	const positions = new Float32Array( numPoints * 3 );
	const colors = new Float32Array( numPoints * 3 );

	let k = 0;

	for ( let i = 0; i < width; i ++ ) {

		for ( let j = 0; j < length; j ++ ) {

			const u = i / width;
			const v = j / length;
			const x = u - 0.5;
			const y = ( Math.cos( u * Math.PI * 4 ) + Math.sin( v * Math.PI * 8 ) ) / 20;
			const z = v - 0.5;

			positions[ 3 * k ] = x;
			positions[ 3 * k + 1 ] = y;
			positions[ 3 * k + 2 ] = z;

			const intensity = ( y + 0.1 ) * 5;
			colors[ 3 * k ] = color.r * intensity;
			colors[ 3 * k + 1 ] = color.g * intensity;
			colors[ 3 * k + 2 ] = color.b * intensity;

			k ++;

		}

	}

	geometry.setAttribute( 'position', new THREE.BufferAttribute( positions, 3 ) );
	geometry.setAttribute( 'color', new THREE.BufferAttribute( colors, 3 ) );
	geometry.computeBoundingBox();

	return geometry;

}

function generatePointcloud( color, width, length ) {

	const geometry = generatePointCloudGeometry( color, width, length );
	const material = new THREE.PointsMaterial( { size: pointSize, vertexColors: true } );

	return new THREE.Points( geometry, material );

}

function generateIndexedPointcloud( color, width, length ) {

	const geometry = generatePointCloudGeometry( color, width, length );
	const numPoints = width * length;
	const indices = new Uint16Array( numPoints );

	let k = 0;

	for ( let i = 0; i < width; i ++ ) {

		for ( let j = 0; j < length; j ++ ) {

			indices[ k ] = k;
			k ++;

		}

	}

	geometry.setIndex( new THREE.BufferAttribute( indices, 1 ) );

	const material = new THREE.PointsMaterial( { size: pointSize, vertexColors: true } );

	return new THREE.Points( geometry, material );

}

function generateIndexedWithOffsetPointcloud( color, width, length ) {

	const geometry = generatePointCloudGeometry( color, width, length );
	const numPoints = width * length;
	const indices = new Uint16Array( numPoints );

	let k = 0;

	for ( let i = 0; i < width; i ++ ) {

		for ( let j = 0; j < length; j ++ ) {

			indices[ k ] = k;
			k ++;

		}

	}

	geometry.setIndex( new THREE.BufferAttribute( indices, 1 ) );
	geometry.addGroup( 0, indices.length );

	const material = new THREE.PointsMaterial( { size: pointSize, vertexColors: true } );

	return new THREE.Points( geometry, material );

}

function init() {

	const container = document.getElementById( 'container' );

	scene = new THREE.Scene();

	timer = new THREE.Timer();
	timer.connect( document );

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 1, 10000 );
	camera.position.set( 10, 10, 10 );
	camera.lookAt( scene.position );
	camera.updateMatrix();

	//

	const pcBuffer = generatePointcloud( new THREE.Color( 1, 0, 0 ), width, length );
	pcBuffer.scale.set( 5, 10, 10 );
	pcBuffer.position.set( - 5, 0, 0 );
	scene.add( pcBuffer );

	const pcIndexed = generateIndexedPointcloud( new THREE.Color( 0, 1, 0 ), width, length );
	pcIndexed.scale.set( 5, 10, 10 );
	pcIndexed.position.set( 0, 0, 0 );
	scene.add( pcIndexed );

	const pcIndexedOffset = generateIndexedWithOffsetPointcloud( new THREE.Color( 0, 1, 1 ), width, length );
	pcIndexedOffset.scale.set( 5, 10, 10 );
	pcIndexedOffset.position.set( 5, 0, 0 );
	scene.add( pcIndexedOffset );

	pointclouds = [ pcBuffer, pcIndexed, pcIndexedOffset ];

	//

	const sphereGeometry = new THREE.SphereGeometry( 0.1, 32, 32 );
	const sphereMaterial = new THREE.MeshBasicMaterial( { color: 0xff0000 } );

	for ( let i = 0; i < 40; i ++ ) {

		const sphere = new THREE.Mesh( sphereGeometry, sphereMaterial );
		scene.add( sphere );
		spheres.push( sphere );

	}

	//

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	container.appendChild( renderer.domElement );

	//

	raycaster = new THREE.Raycaster();
	raycaster.params.Points.threshold = threshold;

	//

	stats = new Stats();
	container.appendChild( stats.dom );

	//

	window.addEventListener( 'resize', onWindowResize );
	document.addEventListener( 'pointermove', onPointerMove );

}

function onPointerMove( event ) {

	pointer.x = ( event.clientX / window.innerWidth ) * 2 - 1;
	pointer.y = - ( event.clientY / window.innerHeight ) * 2 + 1;

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	timer.update();

	render();
	stats.update();

}

function render() {

	camera.applyMatrix4( rotateY );
	camera.updateMatrixWorld();

	raycaster.setFromCamera( pointer, camera );

	const intersections = raycaster.intersectObjects( pointclouds, false );
	intersection = ( intersections.length ) > 0 ? intersections[ 0 ] : null;

	if ( toggle > 0.02 && intersection !== null ) {

		spheres[ spheresIndex ].position.copy( intersection.point );
		spheres[ spheresIndex ].scale.set( 1, 1, 1 );
		spheresIndex = ( spheresIndex + 1 ) % spheres.length;

		toggle = 0;

	}

	for ( let i = 0; i < spheres.length; i ++ ) {

		const sphere = spheres[ i ];
		sphere.scale.multiplyScalar( 0.98 );
		sphere.scale.clampScalar( 0.01, 1 );

	}

	toggle += timer.getDelta();

	renderer.render( scene, camera );

}

import * as THREE from 'three';

let camera, scene, renderer;
let plane;
let pointer, raycaster, isShiftDown = false;

let rollOverMesh, rollOverMaterial;
let cubeGeo, cubeMaterial;

const objects = [];

init();
render();

function init() {

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 1, 10000 );
	camera.position.set( 500, 800, 1300 );
	camera.lookAt( 0, 0, 0 );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xf0f0f0 );

	// roll-over helpers

	const rollOverGeo = new THREE.BoxGeometry( 50, 50, 50 );
	rollOverMaterial = new THREE.MeshBasicMaterial( { color: 0xff0000, opacity: 0.5, transparent: true } );
	rollOverMesh = new THREE.Mesh( rollOverGeo, rollOverMaterial );
	scene.add( rollOverMesh );

	// cubes

	const map = new THREE.TextureLoader().load( 'textures/square-outline-textured.png' );
	map.colorSpace = THREE.SRGBColorSpace;
	cubeGeo = new THREE.BoxGeometry( 50, 50, 50 );
	cubeMaterial = new THREE.MeshLambertMaterial( { color: 0xfeb74c, map: map } );

	// grid

	const gridHelper = new THREE.GridHelper( 1000, 20 );
	scene.add( gridHelper );

	//

	raycaster = new THREE.Raycaster();
	pointer = new THREE.Vector2();

	const geometry = new THREE.PlaneGeometry( 1000, 1000 );
	geometry.rotateX( - Math.PI / 2 );

	plane = new THREE.Mesh( geometry, new THREE.MeshBasicMaterial( { visible: false } ) );
	scene.add( plane );

	objects.push( plane );

	// lights

	const ambientLight = new THREE.AmbientLight( 0x606060, 3 );
	scene.add( ambientLight );

	const directionalLight = new THREE.DirectionalLight( 0xffffff, 3 );
	directionalLight.position.set( 1, 0.75, 0.5 ).normalize();
	scene.add( directionalLight );

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	document.body.appendChild( renderer.domElement );

	document.addEventListener( 'pointermove', onPointerMove );
	document.addEventListener( 'pointerdown', onPointerDown );
	document.addEventListener( 'keydown', onDocumentKeyDown );
	document.addEventListener( 'keyup', onDocumentKeyUp );

	//

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

	render();

}

function onPointerMove( event ) {

	pointer.set( ( event.clientX / window.innerWidth ) * 2 - 1, - ( event.clientY / window.innerHeight ) * 2 + 1 );

	raycaster.setFromCamera( pointer, camera );

	const intersects = raycaster.intersectObjects( objects, false );

	if ( intersects.length > 0 ) {

		const intersect = intersects[ 0 ];

		rollOverMesh.position.copy( intersect.point ).add( intersect.face.normal );
		rollOverMesh.position.divideScalar( 50 ).floor().multiplyScalar( 50 ).addScalar( 25 );

		render();

	}

}

function onPointerDown( event ) {

	pointer.set( ( event.clientX / window.innerWidth ) * 2 - 1, - ( event.clientY / window.innerHeight ) * 2 + 1 );

	raycaster.setFromCamera( pointer, camera );

	const intersects = raycaster.intersectObjects( objects, false );

	if ( intersects.length > 0 ) {

		const intersect = intersects[ 0 ];

		// delete cube

		if ( isShiftDown ) {

			if ( intersect.object !== plane ) {

				scene.remove( intersect.object );

				objects.splice( objects.indexOf( intersect.object ), 1 );

			}

			// create cube

		} else {

			const voxel = new THREE.Mesh( cubeGeo, cubeMaterial );
			voxel.position.copy( intersect.point ).add( intersect.face.normal );
			voxel.position.divideScalar( 50 ).floor().multiplyScalar( 50 ).addScalar( 25 );
			scene.add( voxel );

			objects.push( voxel );

		}

		render();

	}

}

function onDocumentKeyDown( event ) {

	switch ( event.keyCode ) {

		case 16: isShiftDown = true; break;

	}

}

function onDocumentKeyUp( event ) {

	switch ( event.keyCode ) {

		case 16: isShiftDown = false; break;

	}

}

function render() {

	renderer.render( scene, camera );

}

