function createSpotlight( color ) {

	const newObj = new THREE.SpotLight( color, 10 );

	newObj.castShadow = true;
	newObj.angle = 0.3;
	newObj.penumbra = 0.2;
	newObj.decay = 2;
	newObj.distance = 50;

