	tween( spotLight2 );
	tween( spotLight3 );

	setTimeout( updateTweens, 5000 );

}

function animate() {

	TWEEN.update();

	if ( lightHelper1 ) lightHelper1.update();
	if ( lightHelper2 ) lightHelper2.update();
	if ( lightHelper3 ) lightHelper3.update();

	renderer.render( scene, camera );

}

