import { Sky } from 'three/addons/objects/Sky.js';
import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

let renderer, scene, camera, controls, timer, sunLight, sky, sceneEnv, pmremGenerator, renderTarget;

const params = {
	showCascades: false,
	far: 1000,
	resolution: 2048,
	azimuth: 135,
	elevation: 10
};

const _sunDay = new THREE.Color( 0xfff2e3 ), _sunDusk = new THREE.Color( 0xff8a3d );
const _fogDay = new THREE.Color( 0xd8e2ea ), _fogDusk = new THREE.Color( 0xd9a273 );

// tints each fragment by its cascade, using the data of the built-in sun shadow shader

function tintCascades( shader ) {

	shader.fragmentShader = shader.fragmentShader.replace( '#include <opaque_fragment>', /* glsl */`
		#include <opaque_fragment>

		#if defined( USE_SHADOWMAP ) && NUM_SUN_LIGHT_SHADOWS > 0

			float cascade = 0.0;

			for ( int i = 0; i < SUN_LIGHT_CASCADES; i ++ ) {

				cascade += step( sunShadowCascade[ i ].y, vSunShadowWorldPosition.w );

			}

			gl_FragColor.rgb *= 0.7 + 0.3 * cos( cascade * 1.2 + vec3( 0.0, 4.2, 2.1 ) );

		#endif
	` );

}

init();

function updateSun() {

	sunLight.position.setFromSphericalCoords( 1, THREE.MathUtils.degToRad( 90 - params.elevation ), THREE.MathUtils.degToRad( params.azimuth ) );

	// the sun light warms up and fades towards the horizon

	const daylight = Math.min( 1, params.elevation / 30 );

	sunLight.color.lerpColors( _sunDusk, _sunDay, daylight );
	sunLight.intensity = 3 + daylight * 2;

	scene.fog.color.lerpColors( _fogDusk, _fogDay, daylight );

	sky.material.uniforms.sunPosition.value.copy( sunLight.position );

	// light the scene with the sky itself

	if ( renderTarget !== undefined ) renderTarget.dispose();

	sceneEnv.add( sky );
	renderTarget = pmremGenerator.fromScene( sceneEnv );
	scene.add( sky );

	scene.environment = renderTarget.texture;

}

function init() {

	scene = new THREE.Scene();
	scene.fog = new THREE.Fog( 0x000000, 500, 4000 );
	scene.environmentIntensity = 0.5;

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 0.5, 5000 );
	camera.position.set( 60, 8, 0 );
	camera.lookAt( - 60, 8, 0 );

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.shadowMap.enabled = true;
