	scene.add( sunLight );

	updateSun();

	// ground

	const ground = new THREE.Mesh( new THREE.PlaneGeometry( 10000, 10000 ), new THREE.MeshStandardMaterial( { color: 0xa39f8e } ) );
	ground.rotation.x = - Math.PI / 2;
	ground.receiveShadow = true;
	scene.add( ground );

	const dummy = new THREE.Object3D();

	// an avenue of thin posts shows the shadow resolution from up close
	// all the way down to the shadow distance

	const posts = new THREE.InstancedMesh( new THREE.BoxGeometry( 1, 10, 1 ), new THREE.MeshStandardMaterial( { color: 0x475161 } ), 120 );
	posts.castShadow = true;
	posts.receiveShadow = true;
	scene.add( posts );

	for ( let i = 0; i < 60; i ++ ) {

		for ( const side of [ - 1, 1 ] ) {

			dummy.position.set( 30 - i * 17, 5, side * 13 );
			dummy.updateMatrix();
			posts.setMatrixAt( i * 2 + ( side + 1 ) / 2, dummy.matrix );

		}

	}

	// towers for large shadows in the distance

	const towers = new THREE.InstancedMesh( new THREE.BoxGeometry( 10, 1, 10 ), new THREE.MeshStandardMaterial(), 60 );
	towers.castShadow = true;
	towers.receiveShadow = true;
	scene.add( towers );

	const towerColors = [ new THREE.Color( 0x08d9d6 ), new THREE.Color( 0xff2e63 ) ];

	THREE.MathUtils.seededRandom( 6 );

	for ( let i = 0; i < 30; i ++ ) {

		for ( const side of [ - 1, 1 ] ) {

			const height = 20 + THREE.MathUtils.seededRandom() * 40;

			dummy.position.set( - 40 - i * 32 - THREE.MathUtils.seededRandom() * 10, height / 2, side * ( 38 + THREE.MathUtils.seededRandom() * 55 ) );
			dummy.scale.y = height;
			dummy.updateMatrix();

			const index = i * 2 + ( side + 1 ) / 2;
			towers.setMatrixAt( index, dummy.matrix );
			towers.setColorAt( index, towerColors[ ( i + ( side + 1 ) / 2 ) % 2 ] );

		}

	}

	// gui

	const materials = [ ground.material, posts.material, towers.material ];

	const gui = new GUI();

	gui.add( params, 'showCascades' ).name( 'show cascades' ).onChange( function ( value ) {

		for ( const material of materials ) {

			if ( value ) material.onBeforeCompile = tintCascades;
			else delete material.onBeforeCompile;

			material.needsUpdate = true;

		}

	} );

	gui.add( params, 'far', 100, 3000 ).step( 1 ).name( 'shadow far' ).onChange( function ( value ) {

		sunLight.shadow.camera.far = value;

	} );

	gui.add( params, 'resolution', [ 256, 512, 1024, 2048, 4096 ] ).name( 'shadow resolution' ).onChange( function ( value ) {

		sunLight.shadow.mapSize.setScalar( value );

	} );

	gui.add( params, 'azimuth', 0, 360 ).onChange( updateSun );
	gui.add( params, 'elevation', 5, 80 ).onChange( updateSun );

	window.addEventListener( 'resize', function () {

		camera.aspect = window.innerWidth / window.innerHeight;
		camera.updateProjectionMatrix();

		renderer.setSize( window.innerWidth, window.innerHeight );
		controls.handleResize();

	} );

}

function animate() {

	timer.update();

	controls.update( timer.getDelta() );

	renderer.render( scene, camera );

