	if ( model.userData.numBuildingSteps > 1 ) {

		gui.add( guiData, 'buildingStep', 0, model.userData.numBuildingSteps - 1 ).step( 1 ).name( 'Building step' ).onChange( updateObjectsVisibility );

	} else {

