// GUI

function labelize( text ) {

	const parts = text.split( '.' );

	if ( parts.length > 1 ) {

		parts.length -= 1;
		return parts.join( '.' );

	}

	return text;

}

//

function setupWeaponsGUI( character ) {

	const folder = gui.addFolder( 'Weapons' );

	const generateCallback = function ( index ) {

		return function () {

			character.setWeapon( index );
			character.setWireframe( playbackConfig.wireframe );

		};

	};

	const guiItems = [];

	for ( let i = 0; i < character.weapons.length; i ++ ) {

		const name = character.weapons[ i ].name;

		playbackConfig[ name ] = generateCallback( i );
		guiItems[ i ] = folder.add( playbackConfig, name ).name( labelize( name ) );

	}

}

//

function setupSkinsGUI( character ) {

	const folder = gui.addFolder( 'Skins' );

	const generateCallback = function ( index ) {

		return function () {

			character.setSkin( index );

		};

	};

	const guiItems = [];

	for ( let i = 0; i < character.skinsBody.length; i ++ ) {

		const name = character.skinsBody[ i ].name;

		playbackConfig[ name ] = generateCallback( i );
		guiItems[ i ] = folder.add( playbackConfig, name ).name( labelize( name ) );

	}

}

//

function setupGUIAnimations( character ) {

	const folder = gui.addFolder( 'Animations' );

	const generateCallback = function ( animationClip ) {

		return function () {

			character.setAnimation( animationClip.name );

		};

	};

	const guiItems = [];
	const animations = character.meshBody.geometry.animations;

	for ( let i = 0; i < animations.length; i ++ ) {

		const clip = animations[ i ];

		playbackConfig[ clip.name ] = generateCallback( clip );
		guiItems[ i ] = folder.add( playbackConfig, clip.name, clip.name );

	}

}

//

function animate() {

	timer.update();

	render();

	stats.update();

}

function render() {

	const delta = timer.getDelta();

	character.update( delta );

	renderer.render( scene, camera );

}

import * as THREE from 'three';

import Stats from 'three/addons/libs/stats.module.js';

import { SunLight } from 'three/addons/lights/SunLight.js';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { MD2CharacterComplex } from 'three/addons/misc/MD2CharacterComplex.js';
import { Gyroscope } from 'three/addons/misc/Gyroscope.js';

let SCREEN_WIDTH = window.innerWidth;
let SCREEN_HEIGHT = window.innerHeight;

let container, stats;
let camera, scene, renderer;

const characters = [];
let nCharacters = 0;

let cameraControls;

const controls = {

	moveForward: false,
	moveBackward: false,
	moveLeft: false,
	moveRight: false

};

const timer = new THREE.Timer();
timer.connect( document );

init();

function init() {

	container = document.createElement( 'div' );
	document.body.appendChild( container );

	// CAMERA

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 1, 4000 );
	camera.position.set( 0, 150, 1300 );

	// SCENE

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xffffff );
	scene.fog = new THREE.Fog( 0xffffff, 1000, 4000 );

	scene.add( camera );

	// LIGHTS

	scene.add( new THREE.AmbientLight( 0x666666, 3 ) );

	const sunLight = new SunLight( 0xffffff, 7 );
	sunLight.position.set( 200, 450, 500 );
	sunLight.castShadow = true;
	sunLight.shadow.camera.far = 2000;
	scene.add( sunLight );


	//  GROUND

	const gt = new THREE.TextureLoader().load( 'textures/terrain/grasslight-big.jpg' );
	const gg = new THREE.PlaneGeometry( 16000, 16000 );
	const gm = new THREE.MeshPhongMaterial( { color: 0xffffff, map: gt } );

	const ground = new THREE.Mesh( gg, gm );
	ground.rotation.x = - Math.PI / 2;
	ground.material.map.repeat.set( 64, 64 );
	ground.material.map.wrapS = THREE.RepeatWrapping;
	ground.material.map.wrapT = THREE.RepeatWrapping;
	ground.material.map.colorSpace = THREE.SRGBColorSpace;
	// note that because the ground does not cast a shadow, .castShadow is left false
	ground.receiveShadow = true;

	scene.add( ground );

	// RENDERER

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( SCREEN_WIDTH, SCREEN_HEIGHT );
	renderer.setAnimationLoop( animate );
	container.appendChild( renderer.domElement );

	//

	renderer.shadowMap.enabled = true;
	renderer.shadowMap.type = THREE.PCFShadowMap;

	// STATS

	stats = new Stats();
	container.appendChild( stats.dom );

	// EVENTS

	window.addEventListener( 'resize', onWindowResize );
	document.addEventListener( 'keydown', onKeyDown );
	document.addEventListener( 'keyup', onKeyUp );

	// CONTROLS

	cameraControls = new OrbitControls( camera, renderer.domElement );
	cameraControls.target.set( 0, 50, 0 );
	cameraControls.update();

	// CHARACTER

	const configOgro = {

		baseUrl: 'models/md2/ogro/',

		body: 'ogro.md2',
		skins: [ 'grok.jpg', 'ogrobase.png', 'arboshak.png', 'ctf_r.png', 'ctf_b.png', 'darkam.png', 'freedom.png',
				 'gib.png', 'gordogh.png', 'igdosh.png', 'khorne.png', 'nabogro.png',
				 'sharokh.png' ],
		weapons: [[ 'weapon.md2', 'weapon.jpg' ]],
		animations: {
			move: 'run',
			idle: 'stand',
			jump: 'jump',
			attack: 'attack',
			crouchMove: 'cwalk',
			crouchIdle: 'cstand',
			crouchAttach: 'crattack'
		},

		walkSpeed: 350,
		crouchSpeed: 175

	};

	const nRows = 1;
	const nSkins = configOgro.skins.length;

	nCharacters = nSkins * nRows;

	for ( let i = 0; i < nCharacters; i ++ ) {

		const character = new MD2CharacterComplex();
		character.scale = 3;
		character.controls = controls;
		characters.push( character );

	}

	const baseCharacter = new MD2CharacterComplex();
	baseCharacter.scale = 3;

	baseCharacter.onLoadComplete = function () {

		let k = 0;

		for ( let j = 0; j < nRows; j ++ ) {

			for ( let i = 0; i < nSkins; i ++ ) {

				const cloneCharacter = characters[ k ];

				cloneCharacter.shareParts( baseCharacter );

				// cast and receive shadows
				cloneCharacter.enableShadows( true );

				cloneCharacter.setWeapon( 0 );
				cloneCharacter.setSkin( i );

				cloneCharacter.root.position.x = ( i - nSkins / 2 ) * 150;
				cloneCharacter.root.position.z = j * 250;

				scene.add( cloneCharacter.root );

				k ++;

			}

		}

		const gyro = new Gyroscope();
		gyro.add( camera );

		characters[ Math.floor( nSkins / 2 ) ].root.add( gyro );

	};

	baseCharacter.loadParts( configOgro );

}

// EVENT HANDLERS

function onWindowResize() {

	SCREEN_WIDTH = window.innerWidth;
	SCREEN_HEIGHT = window.innerHeight;

	renderer.setSize( SCREEN_WIDTH, SCREEN_HEIGHT );

	camera.aspect = SCREEN_WIDTH / SCREEN_HEIGHT;
	camera.updateProjectionMatrix();

}

function onKeyDown( event ) {

	switch ( event.code ) {

		case 'ArrowUp':
		case 'KeyW': controls.moveForward = true; break;

		case 'ArrowDown':
		case 'KeyS': controls.moveBackward = true; break;

		case 'ArrowLeft':
		case 'KeyA': controls.moveLeft = true; break;

		case 'ArrowRight':
		case 'KeyD': controls.moveRight = true; break;

		// case 'KeyC': controls.crouch = true; break;
		// case 'Space': controls.jump = true; break;
		// case 'ControlLeft':
		// case 'ControlRight': controls.attack = true; break;

	}

}

function onKeyUp( event ) {

	switch ( event.code ) {

		case 'ArrowUp':
		case 'KeyW': controls.moveForward = false; break;

		case 'ArrowDown':
		case 'KeyS': controls.moveBackward = false; break;

		case 'ArrowLeft':
		case 'KeyA': controls.moveLeft = false; break;

		case 'ArrowRight':
		case 'KeyD': controls.moveRight = false; break;

		// case 'KeyC': controls.crouch = false; break;
		// case 'Space': controls.jump = false; break;
		// case 'ControlLeft':
		// case 'ControlRight': controls.attack = false; break;

	}

}

//

function animate() {

	timer.update();

	render();

	stats.update();

}

function render() {

	const delta = timer.getDelta();

	for ( let i = 0; i < nCharacters; i ++ ) {

		characters[ i ].update( delta );

	}

	renderer.render( scene, camera );

}

