import { EXRLoader } from 'three/addons/loaders/EXRLoader.js';

let mesh, renderer, scene, camera;

const API = {
	color: 0xffffff, // sRGB
	exposure: 1.0
};

init();

function init() {

	// renderer
	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	document.body.appendChild( renderer.domElement );

	// tone mapping
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
 	renderer.toneMappingExposure = API.exposure;


	// scene
	scene = new THREE.Scene();

	// camera
	camera = new THREE.PerspectiveCamera( 40, window.innerWidth / window.innerHeight, 1, 100 );
	camera.position.set( 0, 0, 13 );

	// controls
	const controls = new OrbitControls( camera, renderer.domElement );
	controls.addEventListener( 'change', render );
	controls.enableZoom = false;
	controls.enablePan = false;

	// manager
	const manager = new THREE.LoadingManager( render );

	// matcap
	const loaderEXR = new EXRLoader( manager );
	const matcap = loaderEXR.load( 'textures/matcaps/040full.exr' );

	// normalmap
	const loader = new THREE.TextureLoader( manager );

	const normalmap = loader.load( 'models/gltf/LeePerrySmith/Infinite-Level_02_Tangent_SmoothUV.jpg' );

	// model
	new GLTFLoader( manager ).load( 'models/gltf/LeePerrySmith/LeePerrySmith.glb', function ( gltf ) {

		mesh = gltf.scene.children[ 0 ];
		mesh.position.y = - 0.25;

		mesh.material = new THREE.MeshMatcapMaterial( {

			color: new THREE.Color().setHex( API.color ),
			matcap: matcap,
			normalMap: normalmap

		} );

		scene.add( mesh );

	} );

	// gui
	const gui = new GUI();

	gui.addColor( API, 'color' )
		.listen()
		.onChange( function () {

			mesh.material.color.set( API.color );
			render();

		} );

	gui.add( API, 'exposure', 0, 2 )
		.onChange( function () {

			renderer.toneMappingExposure = API.exposure;
			render();

		} );

	gui.domElement.style.webkitUserSelect = 'none';

	// drag 'n drop
	initDragAndDrop();

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	renderer.setSize( window.innerWidth, window.innerHeight );

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	render();

}

function render() {

	renderer.render( scene, camera );

}

//
// drag and drop anywhere in document
//

function updateMatcap( texture ) {

	if ( mesh.material.matcap ) {

		mesh.material.matcap.dispose();

	}

	mesh.material.matcap = texture;

	texture.needsUpdate = true;

	mesh.material.needsUpdate = true; // because the color space can change

	render();

}

function handleJPG( event ) { // PNG, WebP, AVIF, too

	function imgCallback( event ) {

		const texture = new THREE.Texture( event.target );

		texture.colorSpace = THREE.SRGBColorSpace;

		updateMatcap( texture );

	}

	const img = new Image();

	img.onload = imgCallback;

	img.src = event.target.result;

}

function handleEXR( event ) {

	const loader = new EXRLoader();
	const texture = loader.createDataTexture( event.target.result );

	updateMatcap( texture );

}

function loadFile( file ) {

	const filename = file.name;
	const extension = filename.split( '.' ).pop().toLowerCase();

	if ( extension === 'exr' ) {

		const reader = new FileReader();

		reader.addEventListener( 'load', function ( event ) {

			handleEXR( event );

		} );

		reader.readAsArrayBuffer( file );

	} else { // 'jpg', 'png'

		const reader = new FileReader();

		reader.addEventListener( 'load', function ( event ) {

			handleJPG( event );

		} );

		reader.readAsDataURL( file );

	}

}

function initDragAndDrop() {

	document.addEventListener( 'dragover', function ( event ) {

		event.preventDefault();
		event.dataTransfer.dropEffect = 'copy';

	} );

	document.addEventListener( 'drop', function ( event ) {

		event.preventDefault();

		loadFile( event.dataTransfer.files[ 0 ] );

	} );

}

import * as THREE from 'three';

import Stats from 'three/addons/libs/stats.module.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

let camera, scene, renderer, stats;

init();

function init() {

	camera = new THREE.PerspectiveCamera( 27, window.innerWidth / window.innerHeight, 0.1, 100 );
	camera.position.z = 20;

	scene = new THREE.Scene();

	const loader = new GLTFLoader();
	loader.load( 'models/gltf/LeePerrySmith/LeePerrySmith.glb', function ( gltf ) {

		const geometry = gltf.scene.children[ 0 ].geometry;

		let mesh = new THREE.Mesh( geometry, buildTwistMaterial( 2.0 ) );
		mesh.position.x = - 3.5;
		mesh.position.y = - 0.5;
		scene.add( mesh );

		mesh = new THREE.Mesh( geometry, buildTwistMaterial( - 2.0 ) );
		mesh.position.x = 3.5;
		mesh.position.y = - 0.5;
		scene.add( mesh );

	} );

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	const controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 10;
	controls.maxDistance = 50;

	//

	stats = new Stats();
	document.body.appendChild( stats.dom );

	// EVENTS

	window.addEventListener( 'resize', onWindowResize );

}

function buildTwistMaterial( amount ) {

	const material = new THREE.MeshNormalMaterial();
	material.onBeforeCompile = function ( shader ) {

		shader.uniforms.time = { value: 0 };

		shader.vertexShader = 'uniform float time;\n' + shader.vertexShader;
		shader.vertexShader = shader.vertexShader.replace(
			'#include <begin_vertex>',
			[
				`float theta = sin( time + position.y ) / ${ amount.toFixed( 1 ) };`,
				'float c = cos( theta );',
				'float s = sin( theta );',
				'mat3 m = mat3( c, 0, s, 0, 1, 0, -s, 0, c );',
				'vec3 transformed = vec3( position ) * m;',
				'vNormal = vNormal * m;'
			].join( '\n' )
		);

		material.userData.shader = shader;

	};

	// Make sure WebGLRenderer doesn't reuse a single program

	material.customProgramCacheKey = function () {

		return amount.toFixed( 1 );

	};

	return material;

}

//

function onWindowResize() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	camera.aspect = width / height;
	camera.updateProjectionMatrix();

	renderer.setSize( width, height );

}

//

function animate() {

	render();

	stats.update();

}

function render() {

	scene.traverse( function ( child ) {

		if ( child.isMesh ) {

			const shader = child.material.userData.shader;

			if ( shader ) {

				shader.uniforms.time.value = performance.now() / 1000;

			}

		}

	} );

	renderer.render( scene, camera );

}

