import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
import { BleachBypassShader } from 'three/addons/shaders/BleachBypassShader.js';
import { ColorCorrectionShader } from 'three/addons/shaders/ColorCorrectionShader.js';
import { FXAAPass } from 'three/addons/postprocessing/FXAAPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

let container, loader;

let camera, scene, renderer, controls;

let mesh;

let directionalLight, pointLight, ambientLight;

let composer;

const params = {
	enableNormalMap: true,
	normalScale: 1
};

init();

function init() {

	container = document.createElement( 'div' );
	document.body.appendChild( container );

	camera = new THREE.PerspectiveCamera( 27, window.innerWidth / window.innerHeight, 0.1, 100 );
	camera.position.z = 12;

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x494949 );

	// LIGHTS

	ambientLight = new THREE.AmbientLight( 0xffffff );
	scene.add( ambientLight );

	pointLight = new THREE.PointLight( 0xffffff, 30 );
	pointLight.position.set( 0, 0, 6 );

	scene.add( pointLight );

	directionalLight = new THREE.DirectionalLight( 0xffffff, 3 );
	directionalLight.position.set( 1, - 0.5, - 1 );
	scene.add( directionalLight );

	const textureLoader = new THREE.TextureLoader();

	const diffuseMap = textureLoader.load( 'models/gltf/LeePerrySmith/Map-COL.jpg' );
	diffuseMap.colorSpace = THREE.SRGBColorSpace;

	const specularMap = textureLoader.load( 'models/gltf/LeePerrySmith/Map-SPEC.jpg' );
	specularMap.colorSpace = THREE.SRGBColorSpace;

	const normalMap = textureLoader.load( 'models/gltf/LeePerrySmith/Infinite-Level_02_Tangent_SmoothUV.jpg' );

	const material = new THREE.MeshPhongMaterial( {
		color: 0xefefef,
		specular: 0x222222,
		shininess: 35,
		map: diffuseMap,
		specularMap: specularMap,
		normalMap: normalMap,
		normalScale: new THREE.Vector2( params.normalScale, params.normalScale )
	} );

	loader = new GLTFLoader();
	loader.load( 'models/gltf/LeePerrySmith/LeePerrySmith.glb', function ( gltf ) {

		const geometry = gltf.scene.children[ 0 ].geometry;

		mesh = new THREE.Mesh( geometry, material );

		mesh.position.y = - 0.5;

		scene.add( mesh );


	} );

	renderer = new THREE.WebGLRenderer();
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	container.appendChild( renderer.domElement );

	// COMPOSER

	renderer.autoClear = false;

	const renderModel = new RenderPass( scene, camera );

	const effectBleach = new ShaderPass( BleachBypassShader );
	const effectColor = new ShaderPass( ColorCorrectionShader );
	const outputPass = new OutputPass();
	const effectFXAA = new FXAAPass();

	effectBleach.uniforms[ 'opacity' ].value = 0.2;

	effectColor.uniforms[ 'powRGB' ].value.set( 1.4, 1.45, 1.45 );
	effectColor.uniforms[ 'mulRGB' ].value.set( 1.1, 1.1, 1.1 );

	const renderTarget = new THREE.WebGLRenderTarget( window.innerWidth, window.innerHeight, { type: THREE.HalfFloatType, depthTexture: new THREE.DepthTexture() } );

	composer = new EffectComposer( renderer, renderTarget );

	composer.addPass( renderModel );
	composer.addPass( effectBleach );
	composer.addPass( effectColor );
	composer.addPass( outputPass );
	composer.addPass( effectFXAA );

	// EVENTS

	window.addEventListener( 'resize', onWindowResize );

	// GUI

	const gui = new GUI();

	gui.add( params, 'enableNormalMap' ).name( 'enable normal map' ).onChange( ( value ) => {

		material.normalMap = ( value === true ) ? normalMap : null;
		material.needsUpdate = true;

	} );
	gui.add( params, 'normalScale', 0, 2 ).name( 'normal scale' ).onChange( ( value )=> material.normalScale.setScalar( value ) );
	gui.open();

	// CONTROLS

	controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 8;
	controls.maxDistance = 50;
	controls.enablePan = false;
	controls.enableDamping = true;

}

//

function onWindowResize() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	camera.aspect = width / height;
	camera.updateProjectionMatrix();

	renderer.setSize( width, height );
	composer.setSize( width, height );

}

//

function animate() {

	controls.update();

	composer.render();

}

import * as THREE from 'three';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

let renderer, scene, camera;

init();

function init() {

	// renderer
	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setSize( window.innerWidth, window.innerHeight );
	document.body.appendChild( renderer.domElement );


	// scene
	scene = new THREE.Scene();

	// camera
	camera = new THREE.PerspectiveCamera( 40, window.innerWidth / window.innerHeight, 1, 1000 );
	camera.position.set( - 10, 0, 23 );
	scene.add( camera );

	// controls
	const controls = new OrbitControls( camera, renderer.domElement );
	controls.addEventListener( 'change', render );
	controls.minDistance = 10;
	controls.maxDistance = 50;
	controls.enablePan = false;

	// ambient
	scene.add( new THREE.AmbientLight( 0xffffff, 0.6 ) );

	// light
	const light = new THREE.PointLight( 0xffffff, 4.5, 0, 0 );
	camera.add( light );

	// model
	new GLTFLoader().load( 'models/gltf/Nefertiti/Nefertiti.glb', function ( gltf ) {

		gltf.scene.traverse( function ( child ) {

			if ( child.isMesh ) {

				// glTF currently supports only tangent-space normal maps.
				// this model has been modified to demonstrate the use of an object-space normal map.

				child.material.normalMapType = THREE.ObjectSpaceNormalMap;

				// attribute normals are not required with an object-space normal map. remove them.

				child.geometry.deleteAttribute( 'normal' );

				//

				child.material.side = THREE.DoubleSide;

				child.scale.multiplyScalar( 0.5 );

				// recenter

				new THREE.Box3().setFromObject( child ).getCenter( child.position ).multiplyScalar( - 1 );

				scene.add( child );

			}

		} );

		render();

	} );


	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	renderer.setSize( window.innerWidth, window.innerHeight );

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	render();

}

function render() {

	renderer.render( scene, camera );

}

import * as THREE from 'three';

import Stats from 'three/addons/libs/stats.module.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { HDRCubeTextureLoader } from 'three/addons/loaders/HDRCubeTextureLoader.js';

import { FlakesTexture } from 'three/addons/textures/FlakesTexture.js';

let container, stats;

let camera, scene, renderer;

let particleLight;
let group;

init();

function init() {

	container = document.createElement( 'div' );
	document.body.appendChild( container );

	camera = new THREE.PerspectiveCamera( 27, window.innerWidth / window.innerHeight, 0.25, 50 );
	camera.position.z = 10;

	scene = new THREE.Scene();

	group = new THREE.Group();
	scene.add( group );

	new HDRCubeTextureLoader()
		.setPath( 'textures/cube/pisaHDR/' )
		.load( [ 'px.hdr', 'nx.hdr', 'py.hdr', 'ny.hdr', 'pz.hdr', 'nz.hdr' ],
			function ( texture ) {

				const geometry = new THREE.SphereGeometry( .8, 64, 32 );

				const textureLoader = new THREE.TextureLoader();

				const diffuse = textureLoader.load( 'textures/carbon/Carbon.png' );
				diffuse.colorSpace = THREE.SRGBColorSpace;
				diffuse.wrapS = THREE.RepeatWrapping;
				diffuse.wrapT = THREE.RepeatWrapping;
				diffuse.repeat.x = 10;
				diffuse.repeat.y = 10;

				const normalMap = textureLoader.load( 'textures/carbon/Carbon_Normal.png' );
				normalMap.wrapS = THREE.RepeatWrapping;
				normalMap.wrapT = THREE.RepeatWrapping;
				normalMap.repeat.x = 10;
				normalMap.repeat.y = 10;

				const normalMap2 = textureLoader.load( 'textures/water/Water_1_M_Normal.jpg' );

				const normalMap3 = new THREE.CanvasTexture( new FlakesTexture() );
				normalMap3.wrapS = THREE.RepeatWrapping;
				normalMap3.wrapT = THREE.RepeatWrapping;
				normalMap3.repeat.x = 10;
				normalMap3.repeat.y = 6;
				normalMap3.anisotropy = 16;

				const normalMap4 = textureLoader.load( 'textures/golfball.jpg' );

				const clearcoatNormalMap = textureLoader.load( 'textures/pbr/Scratched_gold/Scratched_gold_01_1K_Normal.png' );

				// car paint

				let material = new THREE.MeshPhysicalMaterial( {
					clearcoat: 1.0,
					clearcoatRoughness: 0.1,
					metalness: 0.9,
					roughness: 0.5,
					color: 0x0000ff,
					normalMap: normalMap3,
					normalScale: new THREE.Vector2( 0.15, 0.15 )
				} );

				let mesh = new THREE.Mesh( geometry, material );
				mesh.position.x = - 1;
				mesh.position.y = 1;
				group.add( mesh );

				// fibers

				material = new THREE.MeshPhysicalMaterial( {
					roughness: 0.5,
					clearcoat: 1.0,
					clearcoatRoughness: 0.1,
					map: diffuse,
					normalMap: normalMap
				} );
				mesh = new THREE.Mesh( geometry, material );
				mesh.position.x = 1;
				mesh.position.y = 1;
				group.add( mesh );

				// golf

				material = new THREE.MeshPhysicalMaterial( {
					metalness: 0.0,
					roughness: 0.1,
					clearcoat: 1.0,
					normalMap: normalMap4,
					clearcoatNormalMap: clearcoatNormalMap,

					// y scale is negated to compensate for normal map handedness.
					clearcoatNormalScale: new THREE.Vector2( 2.0, - 2.0 )
				} );
				mesh = new THREE.Mesh( geometry, material );
				mesh.position.x = - 1;
				mesh.position.y = - 1;
				group.add( mesh );

				// clearcoat + normalmap

				material = new THREE.MeshPhysicalMaterial( {
					clearcoat: 1.0,
					metalness: 1.0,
					color: 0xff0000,
					normalMap: normalMap2,
					normalScale: new THREE.Vector2( 0.15, 0.15 ),
					clearcoatNormalMap: clearcoatNormalMap,

					// y scale is negated to compensate for normal map handedness.
					clearcoatNormalScale: new THREE.Vector2( 2.0, - 2.0 )
				} );
				mesh = new THREE.Mesh( geometry, material );
				mesh.position.x = 1;
				mesh.position.y = - 1;
				group.add( mesh );

				//

				scene.background = texture;
				scene.environment = texture;

			}

		);

	// LIGHTS

	particleLight = new THREE.Mesh(
		new THREE.SphereGeometry( .05, 8, 8 ),
		new THREE.MeshBasicMaterial( { color: 0xffffff } )
	);
	scene.add( particleLight );

	particleLight.add( new THREE.PointLight( 0xffffff, 30 ) );

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	container.appendChild( renderer.domElement );

	//

	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.toneMappingExposure = 1.25;

	//


	//

	stats = new Stats();
	container.appendChild( stats.dom );

	// EVENTS

	const controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 3;
	controls.maxDistance = 30;

	window.addEventListener( 'resize', onWindowResize );

}

//

function onWindowResize() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	camera.aspect = width / height;
	camera.updateProjectionMatrix();

	renderer.setSize( width, height );

}

//

function animate() {

	render();

	stats.update();

}

function render() {

	const timer = Date.now() * 0.00025;

	particleLight.position.x = Math.sin( timer * 7 ) * 3;
	particleLight.position.y = Math.cos( timer * 5 ) * 4;
	particleLight.position.z = Math.cos( timer * 3 ) * 3;

	for ( let i = 0; i < group.children.length; i ++ ) {

		const child = group.children[ i ];
		child.rotation.y += 0.005;

	}

	renderer.render( scene, camera );

}

import * as THREE from 'three';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';
