import { TextGeometry } from 'three/addons/geometries/TextGeometry.js';

const ACTION_SELECT = 1, ACTION_NONE = 0;
const curveHandles = [];
const mouse = new THREE.Vector2();

let stats;
let scene,
	camera,
	renderer,
	rayCaster,
	control,
	flow,
	action = ACTION_NONE;

init();

function init() {

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera(
		40,
		window.innerWidth / window.innerHeight,
		1,
		1000
	);
	camera.position.set( 2, 2, 4 );
	camera.lookAt( scene.position );

	const boxGeometry = new THREE.BoxGeometry( 0.1, 0.1, 0.1 );
	const boxMaterial = new THREE.MeshBasicMaterial();

	const curves = [[
		{ x: 1, y: - 0.5, z: - 1 },
		{ x: 1, y: - 0.5, z: 1 },
		{ x: - 1, y: - 0.5, z: 1 },
		{ x: - 1, y: - 0.5, z: - 1 },
	],
	[
		{ x: - 1, y: 0.5, z: - 1 },
		{ x: - 1, y: 0.5, z: 1 },
		{ x: 1, y: 0.5, z: 1 },
		{ x: 1, y: 0.5, z: - 1 },
	]].map( function ( curvePoints ) {

		const curveVertices = curvePoints.map( function ( handlePos ) {

			const handle = new THREE.Mesh( boxGeometry, boxMaterial );
			handle.position.copy( handlePos );
			curveHandles.push( handle );
			scene.add( handle );
			return handle.position;

		} );

		const curve = new THREE.CatmullRomCurve3( curveVertices );
		curve.curveType = 'centripetal';
		curve.closed = true;

		const points = curve.getPoints( 50 );
		const line = new THREE.LineLoop(
			new THREE.BufferGeometry().setFromPoints( points ),
			new THREE.LineBasicMaterial( { color: 0x00ff00 } )
		);

		scene.add( line );

		return {
			curve,
			line
		};

	} );


	//

	const light = new THREE.DirectionalLight( 0xffaa33, 3 );
	light.position.set( - 10, 10, 10 );
	scene.add( light );

	const light2 = new THREE.AmbientLight( 0x003973, 3 );
