let camera, scene, renderer, timer;

let mesh;

let sign = 1;
const speed = 0.5;

init();

function init() {

	const container = document.getElementById( 'container' );

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.2, 100 );
	camera.position.set( 0, 5, 5 );

