	renderer.setScissor( 0, 0, halfWidth - 1, container.offsetHeight );
	composer1.render();

	renderer.setScissor( halfWidth, 0, halfWidth, container.offsetHeight );
	composer2.render();

	renderer.setScissorTest( false );

}

