function exportGLTF() {

	const exporter = new GLTFExporter();
	const snapshot = mesh.clone();
	snapshot.geometry = sculptor.getGeometry();

	exporter.parse( snapshot, function ( buffer ) {

		const blob = new Blob( [ buffer ], { type: 'application/octet-stream' } );
