		link.href = objectURL;
		link.download = 'sculpt.glb';
		link.click();

		setTimeout( function () {

			URL.revokeObjectURL( objectURL );
			link.removeAttribute( 'href' );

		}, 0 );

	}, function ( error ) {

		console.error( error );

	}, { binary: true } );

