import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { ImprovedNoise } from 'three/addons/math/ImprovedNoise.js';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

let renderer, scene, camera;
let mesh;

init();

function init() {

	renderer = new THREE.WebGLRenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 0.1, 100 );
	camera.position.set( 0, 0, 1.5 );

	new OrbitControls( camera, renderer.domElement );

	// Sky

	const canvas = document.createElement( 'canvas' );
	canvas.width = 1;
	canvas.height = 32;

	const context = canvas.getContext( '2d' );
	const gradient = context.createLinearGradient( 0, 0, 0, 32 );
	gradient.addColorStop( 0.0, '#014a84' );
	gradient.addColorStop( 0.5, '#0561a0' );
	gradient.addColorStop( 1.0, '#437ab6' );
	context.fillStyle = gradient;
	context.fillRect( 0, 0, 1, 32 );

	const skyMap = new THREE.CanvasTexture( canvas );
	skyMap.colorSpace = THREE.SRGBColorSpace;

	const sky = new THREE.Mesh(
		new THREE.SphereGeometry( 10 ),
		new THREE.MeshBasicMaterial( { map: skyMap, side: THREE.BackSide } )
	);
	scene.add( sky );

	// Texture

	const size = 128;
	const data = new Uint8Array( size * size * size );

	let i = 0;
	const scale = 0.05;
	const perlin = new ImprovedNoise();
	const vector = new THREE.Vector3();

	for ( let z = 0; z < size; z ++ ) {

		for ( let y = 0; y < size; y ++ ) {

			for ( let x = 0; x < size; x ++ ) {

				const d = 1.0 - vector.set( x, y, z ).subScalar( size / 2 ).divideScalar( size ).length();
				data[ i ] = ( 128 + 128 * perlin.noise( x * scale / 1.5, y * scale, z * scale / 1.5 ) ) * d * d;
				i ++;

			}

		}

	}

	const texture = new THREE.Data3DTexture( data, size, size, size );
	texture.format = THREE.RedFormat;
	texture.minFilter = THREE.LinearFilter;
	texture.magFilter = THREE.LinearFilter;
	texture.unpackAlignment = 1;
	texture.needsUpdate = true;

	// Material

	const vertexShader = /* glsl */`
		in vec3 position;

		uniform mat4 modelMatrix;
		uniform mat4 modelViewMatrix;
		uniform mat4 projectionMatrix;
		uniform vec3 cameraPos;

		out vec3 vOrigin;
		out vec3 vDirection;

		void main() {
			vec4 mvPosition = modelViewMatrix * vec4( position, 1.0 );

			vOrigin = vec3( inverse( modelMatrix ) * vec4( cameraPos, 1.0 ) ).xyz;
			vDirection = position - vOrigin;

			gl_Position = projectionMatrix * mvPosition;
		}
	`;

	const fragmentShader = /* glsl */`
		precision highp float;
		precision highp sampler3D;

		uniform mat4 modelViewMatrix;
		uniform mat4 projectionMatrix;

		in vec3 vOrigin;
		in vec3 vDirection;

		out vec4 color;

		uniform vec3 base;
		uniform sampler3D map;

		uniform float threshold;
		uniform float range;
		uniform float opacity;
		uniform float steps;
		uniform float frame;

		uint wang_hash(uint seed)
		{
				seed = (seed ^ 61u) ^ (seed >> 16u);
				seed *= 9u;
				seed = seed ^ (seed >> 4u);
				seed *= 0x27d4eb2du;
				seed = seed ^ (seed >> 15u);
				return seed;
		}

		float randomFloat(inout uint seed)
		{
				return float(wang_hash(seed)) / 4294967296.;
		}

		vec2 hitBox( vec3 orig, vec3 dir ) {
			const vec3 box_min = vec3( - 0.5 );
			const vec3 box_max = vec3( 0.5 );
			vec3 inv_dir = 1.0 / dir;
			vec3 tmin_tmp = ( box_min - orig ) * inv_dir;
			vec3 tmax_tmp = ( box_max - orig ) * inv_dir;
			vec3 tmin = min( tmin_tmp, tmax_tmp );
			vec3 tmax = max( tmin_tmp, tmax_tmp );
			float t0 = max( tmin.x, max( tmin.y, tmin.z ) );
			float t1 = min( tmax.x, min( tmax.y, tmax.z ) );
			return vec2( t0, t1 );
		}

		float sample1( vec3 p ) {
			return texture( map, p ).r;
		}

		float shading( vec3 coord ) {
			float step = 0.01;
			return sample1( coord + vec3( - step ) ) - sample1( coord + vec3( step ) );
		}

		vec4 linearToSRGB( in vec4 value ) {
			return vec4( mix( pow( value.rgb, vec3( 0.41666 ) ) * 1.055 - vec3( 0.055 ), value.rgb * 12.92, vec3( lessThanEqual( value.rgb, vec3( 0.0031308 ) ) ) ), value.a );
		}

		void main(){
			vec3 rayDir = normalize( vDirection );
			vec2 bounds = hitBox( vOrigin, rayDir );

			if ( bounds.x > bounds.y ) discard;

			bounds.x = max( bounds.x, 0.0 );

			float stepSize = ( bounds.y - bounds.x ) / steps;

			// Jitter

			// Nice little seed from
			// https://blog.demofox.org/2020/05/25/casual-shadertoy-path-tracing-1-basic-camera-diffuse-emissive/
			uint seed = uint( gl_FragCoord.x ) * uint( 1973 ) + uint( gl_FragCoord.y ) * uint( 9277 ) + uint( frame ) * uint( 26699 );
			vec3 size = vec3( textureSize( map, 0 ) );
			float randNum = randomFloat( seed ) * 2.0 - 1.0;
			vec3 p = vOrigin + bounds.x * rayDir;
			p += rayDir * randNum * ( 1.0 / size );

			//

			vec4 ac = vec4( base, 0.0 );

			for ( float i = 0.0; i < steps; i += 1.0 ) {

				float t = bounds.x + i * stepSize;

				float d = sample1( p + 0.5 );

				d = smoothstep( threshold - range, threshold + range, d ) * opacity;

				float col = shading( p + 0.5 ) * 3.0 + ( ( p.x + p.y ) * 0.25 ) + 0.2;

				ac.rgb += ( 1.0 - ac.a ) * d * col;

				ac.a += ( 1.0 - ac.a ) * d;

				if ( ac.a >= 0.95 ) break;

				p += rayDir * stepSize;

			}

			color = linearToSRGB( ac );

			if ( color.a == 0.0 ) discard;

		}
	`;

	const geometry = new THREE.BoxGeometry( 1, 1, 1 );
	const material = new THREE.RawShaderMaterial( {
		glslVersion: THREE.GLSL3,
		uniforms: {
			base: { value: new THREE.Color( 0x798aa0 ) },
			map: { value: texture },
			cameraPos: { value: new THREE.Vector3() },
			threshold: { value: 0.25 },
			opacity: { value: 0.25 },
			range: { value: 0.1 },
			steps: { value: 100 },
			frame: { value: 0 }
		},
		vertexShader,
		fragmentShader,
		side: THREE.BackSide,
		transparent: true
	} );

	mesh = new THREE.Mesh( geometry, material );
	scene.add( mesh );

	//

	const parameters = {
		threshold: 0.25,
		opacity: 0.25,
		range: 0.1,
		steps: 100
	};

	function update() {

		material.uniforms.threshold.value = parameters.threshold;
		material.uniforms.opacity.value = parameters.opacity;
		material.uniforms.range.value = parameters.range;
		material.uniforms.steps.value = parameters.steps;

	}

	const gui = new GUI();
	gui.add( parameters, 'threshold', 0, 1, 0.01 ).onChange( update );
	gui.add( parameters, 'opacity', 0, 1, 0.01 ).onChange( update );
	gui.add( parameters, 'range', 0, 1, 0.01 ).onChange( update );
	gui.add( parameters, 'steps', 0, 200, 1 ).onChange( update );

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	mesh.material.uniforms.cameraPos.value.copy( camera.position );
	mesh.rotation.y = - performance.now() / 7500;

	mesh.material.uniforms.frame.value ++;

	renderer.render( scene, camera );

}

import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { VOXLoader, buildData3DTexture } from 'three/addons/loaders/VOXLoader.js';

let renderer, scene, camera, controls, timer;

init();

function init() {

	renderer = new THREE.WebGLRenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 0.1, 1000 );
	camera.position.set( 0, 0, 4 );

	controls = new OrbitControls( camera, renderer.domElement );
	controls.autoRotate = true;
	controls.autoRotateSpeed = - 1.0;
	controls.enableDamping = true;

	timer = new THREE.Timer();
	timer.connect( document );

	// Material

	const vertexShader = /* glsl */`
		in vec3 position;
		in mat4 instanceMatrix;

		uniform mat4 modelMatrix;
		uniform mat4 modelViewMatrix;
		uniform mat4 projectionMatrix;
		uniform vec3 cameraPos;

		out vec4 vScreenPosition;
		out mat4 vInstanceToViewMatrix;

		void main() {
			vec4 mvPosition = modelViewMatrix * instanceMatrix * vec4( position, 1.0 );

			gl_Position = projectionMatrix * mvPosition;
			vScreenPosition = vec4( gl_Position.xy, 0.0, gl_Position.w );
			vInstanceToViewMatrix = modelViewMatrix * instanceMatrix;
		}
	`;

	const fragmentShader = /* glsl */`
		precision highp float;
		precision highp sampler3D;

		uniform mat4 viewMatrix;
		uniform mat4 modelViewMatrix;
		uniform mat4 projectionMatrix;

		in vec4 vScreenPosition;
		in mat4 vInstanceToViewMatrix;

		out vec4 color;

		uniform sampler3D map;

		vec2 hitBox( vec3 orig, vec3 dir ) {
			const vec3 box_min = vec3( - 0.5 );
			const vec3 box_max = vec3( 0.5 );
			vec3 inv_dir = 1.0 / dir;
			vec3 tmin_tmp = ( box_min - orig ) * inv_dir;
			vec3 tmax_tmp = ( box_max - orig ) * inv_dir;
			vec3 tmin = min( tmin_tmp, tmax_tmp );
			vec3 tmax = max( tmin_tmp, tmax_tmp );
			float t0 = max( tmin.x, max( tmin.y, tmin.z ) );
			float t1 = min( tmax.x, min( tmax.y, tmax.z ) );
			return vec2( t0, t1 );
		}

		float sample1( vec3 p ) {
			return texture( map, p ).r;
		}

		#define epsilon .0001

		vec3 normal( vec3 coord ) {
			if ( coord.x < epsilon ) return vec3( 1.0, 0.0, 0.0 );
			if ( coord.y < epsilon ) return vec3( 0.0, 1.0, 0.0 );
			if ( coord.z < epsilon ) return vec3( 0.0, 0.0, 1.0 );
			if ( coord.x > 1.0 - epsilon ) return vec3( - 1.0, 0.0, 0.0 );
			if ( coord.y > 1.0 - epsilon ) return vec3( 0.0, - 1.0, 0.0 );
			if ( coord.z > 1.0 - epsilon ) return vec3( 0.0, 0.0, - 1.0 );

			float step = 0.01;
			float x = sample1( coord + vec3( - step, 0.0, 0.0 ) ) - sample1( coord + vec3( step, 0.0, 0.0 ) );
			float y = sample1( coord + vec3( 0.0, - step, 0.0 ) ) - sample1( coord + vec3( 0.0, step, 0.0 ) );
			float z = sample1( coord + vec3( 0.0, 0.0, - step ) ) - sample1( coord + vec3( 0.0, 0.0, step ) );

			return normalize( vec3( x, y, z ) );
		}

		void main() {

			// perform w divide in the fragment shader to avoid interpolation artifacts
			vec2 screenUv = vScreenPosition.xy / vScreenPosition.w;
			mat4 invProjectionMatrix = inverse( projectionMatrix );
			mat4 invInstanceToViewMatrix = inverse( vInstanceToViewMatrix );

			// get camera ray
			vec4 temp;
			vec3 camRayOrigin, camRayEnd;
			temp = invProjectionMatrix * vec4( screenUv, - 1.0, 1.0 );
			camRayOrigin = temp.xyz / temp.w;

			temp = invProjectionMatrix * vec4( screenUv, 1.0, 1.0 );
			camRayEnd = temp.xyz / temp.w;

			// get local ray
			vec3 instRayOrigin, instRayDirection, instRayEnd;
			instRayOrigin = ( invInstanceToViewMatrix * vec4( camRayOrigin, 1.0 ) ).xyz;
			instRayEnd = ( invInstanceToViewMatrix * vec4( camRayEnd, 1.0 ) ).xyz;
			instRayDirection = normalize( instRayEnd - instRayOrigin );

			// calculate the start of the ray at the box edge
			vec2 bounds = hitBox( instRayOrigin, instRayDirection );

			if ( bounds.x > bounds.y ) discard;

			bounds.x = max( bounds.x, 0.0 );

			float stepSize = ( bounds.y - bounds.x ) / 100.0;

			vec3 p;

			// march through the volume
			for ( float i = 0.0; i < 100.0; i += 1.0 ) {

				float t = bounds.x + i * stepSize;
				p = instRayOrigin + t * instRayDirection;
				float d = sample1( p + 0.5 );

				if ( d > 0.5 ) {

					color.rgb = p * 2.0;
					color.a = 1.;
					break;

				}

			}

			if ( color.a == 0.0 ) discard;

			// calculate the final point in the ndc coords
			vec4 ndc = projectionMatrix * vInstanceToViewMatrix * vec4( p, 1.0 );
			ndc /= ndc.w;

			// map the ndc coordinate to depth
			// https://stackoverflow.com/questions/10264949/glsl-gl-fragcoord-z-calculation-and-setting-gl-fragdepth
			float far = gl_DepthRange.far;
			float near = gl_DepthRange.near;
			gl_FragDepth = ( ( ( far - near ) * ndc.z ) + near + far ) / 2.0;

		}
	`;

	const loader = new VOXLoader();
	loader.load( 'models/vox/menger.vox', function ( result ) {

		const chunks = result.chunks;

		for ( let i = 0; i < chunks.length; i ++ ) {

			const chunk = chunks[ i ];

			const geometry = new THREE.BoxGeometry( 1, 1, 1 );
			const material = new THREE.RawShaderMaterial( {
				glslVersion: THREE.GLSL3,
				uniforms: {
					map: { value: buildData3DTexture( chunk ) },
					cameraPos: { value: new THREE.Vector3() }
				},
				vertexShader,
				fragmentShader,
				side: THREE.BackSide
			} );

			const mesh = new THREE.InstancedMesh( geometry, material, 50000 );
			mesh.onBeforeRender = function () {

				this.material.uniforms.cameraPos.value.copy( camera.position );

			};

			const transform = new THREE.Object3D();

			for ( let i = 0; i < mesh.count; i ++ ) {

				transform.position.random().subScalar( 0.5 ).multiplyScalar( 150 );
				transform.rotation.x = Math.random() * Math.PI;
				transform.rotation.y = Math.random() * Math.PI;
				transform.rotation.z = Math.random() * Math.PI;
				transform.updateMatrix();

				mesh.setMatrixAt( i, transform.matrix );

			}

			scene.add( mesh );

		}

	} );

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	timer.update();

	const delta = timer.getDelta();
	controls.update( delta );

	renderer.render( scene, camera );

}

import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { ImprovedNoise } from 'three/addons/math/ImprovedNoise.js';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

let renderer, scene, camera;
let mesh;

init();

function init() {

	renderer = new THREE.WebGLRenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 0.1, 100 );
	camera.position.set( 0, 0, 2 );

	new OrbitControls( camera, renderer.domElement );

	// Texture

	const size = 128;
	const data = new Uint8Array( size * size * size );

	let i = 0;
	const perlin = new ImprovedNoise();
	const vector = new THREE.Vector3();

	for ( let z = 0; z < size; z ++ ) {

		for ( let y = 0; y < size; y ++ ) {

			for ( let x = 0; x < size; x ++ ) {

				vector.set( x, y, z ).divideScalar( size );

				const d = perlin.noise( vector.x * 6.5, vector.y * 6.5, vector.z * 6.5 );

				data[ i ++ ] = d * 128 + 128;

			}

		}

	}

	const texture = new THREE.Data3DTexture( data, size, size, size );
	texture.format = THREE.RedFormat;
	texture.minFilter = THREE.LinearFilter;
	texture.magFilter = THREE.LinearFilter;
	texture.unpackAlignment = 1;
	texture.needsUpdate = true;

	// Material

	const vertexShader = /* glsl */`
		in vec3 position;

		uniform mat4 modelMatrix;
		uniform mat4 modelViewMatrix;
		uniform mat4 projectionMatrix;
		uniform vec3 cameraPos;

		out vec3 vOrigin;
		out vec3 vDirection;

		void main() {
			vec4 mvPosition = modelViewMatrix * vec4( position, 1.0 );

			vOrigin = vec3( inverse( modelMatrix ) * vec4( cameraPos, 1.0 ) ).xyz;
			vDirection = position - vOrigin;

			gl_Position = projectionMatrix * mvPosition;
		}
	`;

	const fragmentShader = /* glsl */`
		precision highp float;
		precision highp sampler3D;

		uniform mat4 modelViewMatrix;
		uniform mat4 projectionMatrix;

		in vec3 vOrigin;
		in vec3 vDirection;

		out vec4 color;

		uniform sampler3D map;

		uniform float threshold;
		uniform float steps;
		uniform bool refine;

		#define REFINEMENT_STEPS 4

		vec2 hitBox( vec3 orig, vec3 dir ) {
			const vec3 box_min = vec3( - 0.5 );
			const vec3 box_max = vec3( 0.5 );
			vec3 inv_dir = 1.0 / dir;
			vec3 tmin_tmp = ( box_min - orig ) * inv_dir;
			vec3 tmax_tmp = ( box_max - orig ) * inv_dir;
			vec3 tmin = min( tmin_tmp, tmax_tmp );
			vec3 tmax = max( tmin_tmp, tmax_tmp );
			float t0 = max( tmin.x, max( tmin.y, tmin.z ) );
			float t1 = min( tmax.x, min( tmax.y, tmax.z ) );
			return vec2( t0, t1 );
		}

		float sample1( vec3 p ) {
			return texture( map, p ).r;
		}

		#define epsilon .0001

		vec3 normal( vec3 coord ) {
			if ( coord.x < epsilon ) return vec3( 1.0, 0.0, 0.0 );
			if ( coord.y < epsilon ) return vec3( 0.0, 1.0, 0.0 );
			if ( coord.z < epsilon ) return vec3( 0.0, 0.0, 1.0 );
			if ( coord.x > 1.0 - epsilon ) return vec3( - 1.0, 0.0, 0.0 );
			if ( coord.y > 1.0 - epsilon ) return vec3( 0.0, - 1.0, 0.0 );
			if ( coord.z > 1.0 - epsilon ) return vec3( 0.0, 0.0, - 1.0 );

			float step = 0.01;
			float x = sample1( coord + vec3( - step, 0.0, 0.0 ) ) - sample1( coord + vec3( step, 0.0, 0.0 ) );
			float y = sample1( coord + vec3( 0.0, - step, 0.0 ) ) - sample1( coord + vec3( 0.0, step, 0.0 ) );
			float z = sample1( coord + vec3( 0.0, 0.0, - step ) ) - sample1( coord + vec3( 0.0, 0.0, step ) );

			return normalize( vec3( x, y, z ) );
		}

		void main(){

			vec3 rayDir = normalize( vDirection );
			vec2 bounds = hitBox( vOrigin, rayDir );

			if ( bounds.x > bounds.y ) discard;

			bounds.x = max( bounds.x, 0.0 );

			float stepSize = ( bounds.y - bounds.x ) / steps;

			for ( float i = 0.0; i < steps; i += 1.0 ) {

				float t = bounds.x + i * stepSize;
				vec3 p = vOrigin + t * rayDir;
				float d = sample1( p + 0.5 );

				if ( d > threshold ) {

					if ( refine ) {

						// The surface lies between the previous ray parameter i.e. (t - stepSize)
						// and the current ray parameter (t). Bisect that interval to localize
						// the crossing precisely.

						float t0 = max( t - stepSize, bounds.x );
						float t1 = t;

						for ( int j = 0; j < REFINEMENT_STEPS; j ++ ) {

							float tm = ( t0 + t1 ) * 0.5;
							float dm = sample1( vOrigin + tm * rayDir + 0.5 );

							bool isGreater = dm > threshold;
							t1 = isGreater ? tm : t1;
							t0 = isGreater ? t0 : tm;

						}

						p = vOrigin + t1 * rayDir;

					}

					color.rgb = normal( p + 0.5 ) * 0.5 + ( p * 1.5 + 0.25 );
					color.a = 1.;
					break;

				}

			}

			if ( color.a == 0.0 ) discard;

		}
	`;

	const geometry = new THREE.BoxGeometry( 1, 1, 1 );
	const material = new THREE.RawShaderMaterial( {
		glslVersion: THREE.GLSL3,
		uniforms: {
			map: { value: texture },
			cameraPos: { value: new THREE.Vector3() },
			threshold: { value: 0.6 },
			steps: { value: 200 },
			refine: { value: true }
		},
		vertexShader,
		fragmentShader,
		side: THREE.BackSide,
	} );

	mesh = new THREE.Mesh( geometry, material );
	scene.add( mesh );

	//

	const parameters = { threshold: 0.6, steps: 200, refine: true };

	function update() {

		material.uniforms.threshold.value = parameters.threshold;
		material.uniforms.steps.value = parameters.steps;
		material.uniforms.refine.value = parameters.refine;

	}

	const gui = new GUI();
	gui.add( parameters, 'threshold', 0, 1, 0.01 ).onChange( update );
	gui.add( parameters, 'steps', 0, 300, 1 ).onChange( update );
	gui.add( parameters, 'refine' ).onChange( update );

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	mesh.material.uniforms.cameraPos.value.copy( camera.position );

	renderer.render( scene, camera );

}

import * as THREE from 'three';
import * as TWEEN from 'tween';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { HDRLoader } from 'three/addons/loaders/HDRLoader.js';
import { DRACOLoader, DRACO_GLTF_CONFIG } from 'three/addons/loaders/DRACOLoader.js';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { TAARenderPass } from 'three/addons/postprocessing/TAARenderPass.js';

let camera, scene, renderer;
let gui, dirLight, pointLight, controls, bloomPass, taaPass;
let ready = false;

const meshes = {};
const materials = {};
const torad = Math.PI / 180;

const setting = {
	roughness: 0.1,
	metalness: 1.0,
	opacity: 0.8,
	threshold: 0,
	strength: 0.007,
	radius: 0.0,
	postProcess: false
};

init();

function init() {

	const container = document.getElementById( 'container' );

	camera = new THREE.PerspectiveCamera( 55, window.innerWidth / window.innerHeight, 0.1, 20 );
	camera.position.set( 0.8, 0.5, - 1.5 );

	scene = new THREE.Scene();

	renderer = new THREE.WebGLRenderer( { antialias: true, outputBufferType: THREE.HalfFloatType } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.toneMapping = THREE.NeutralToneMapping;
	renderer.toneMappingExposure = 0.7;
	renderer.shadowMap.enabled = true;
	container.appendChild( renderer.domElement );

	taaPass = new TAARenderPass( scene, camera );
	taaPass.sampleLevel = 2;

	bloomPass = new UnrealBloomPass( new THREE.Vector2( window.innerWidth, window.innerHeight ), 1.5, 0.4, 0.85 );
	bloomPass.threshold = setting.threshold;
	bloomPass.strength = setting.strength;
	bloomPass.radius = setting.radius;

	new HDRLoader()
		.setPath( 'textures/equirectangular/' )
		.load( 'lobe.hdr', function ( texture ) {

			texture.mapping = THREE.EquirectangularReflectionMapping;
			scene.background = texture;
			scene.environment = texture;
			scene.backgroundBlurriness = 0.5;
			scene.backgroundIntensity = 1.0;
			scene.environmentIntensity = 1.5;

			// model

			const loader = new GLTFLoader().setPath( 'models/gltf/' );
			loader.setDRACOLoader( new DRACOLoader().setDecoderPath( DRACO_GLTF_CONFIG ) );
			loader.load( 'rolex.glb', function ( gltf ) {

				gltf.scene.rotation.x = Math.PI * 0.25;

				gltf.scene.traverse( ( child ) => {

					if ( child.isMesh || child.isGroup ) {

						if ( child.isMesh ) {

							child.material.vertexColors = false;
							if ( materials[ child.material.name ] ) child.material = materials[ child.material.name ];
							else materials[ child.material.name ] = child.material;
							if ( child.name !== 'glass' && child.name !== 'floor' ) {

								child.receiveShadow = true;
							    child.castShadow = true;

							}

						}

						meshes[ child.name ] = child;

					}

				} );

				scene.add( gltf.scene );

				meshes.glass.material = new THREE.MeshPhysicalMaterial( {
					color: 0x020205,
					transparent: true, opacity: setting.opacity,
					metalness: 0, roughness: 0,
					iridescence: 0.3,
					clearcoat: 1.0,
					blending: THREE.AdditiveBlending
				} );

				ready = true;

				createGUI();

			} );

		} );



	controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 0.3;
	controls.maxDistance = 10;
	controls.target.set( 0, - 0.1, 0 );
	controls.enableDamping = true;
	controls.dampingFactor = 0.05;
	controls.update();

	dirLight = new THREE.DirectionalLight( 0xFFFFFF, 6 );
	dirLight.position.set( 0.2, 0.6, 0.4 );
	dirLight.castShadow = true;
	scene.add( dirLight );
	const shadow = dirLight.shadow;
	shadow.mapSize.width = shadow.mapSize.height = 2048;
	shadow.radius = 8;
	shadow.bias = - 0.0005;
	const shadowCam = shadow.camera, s = 0.5;
	shadowCam.near = 0.1;
	shadowCam.far = 2;
	shadowCam.right = shadowCam.top	= s;
	shadowCam.left = shadowCam.bottom = - s;
	// debug shadow
	//scene.add(  new THREE.CameraHelper(shadowCam) );

	pointLight = new THREE.PointLight( 0x7b8cad, 1, 0, 2 );
	pointLight.position.set( - 0.3, - 0.2, - 0.2 );
	scene.add( pointLight );

	window.addEventListener( 'resize', onWindowResize );

	moveCamera();

}

function moveCamera() {

	controls.enabled = false;
	controls.enableDamping = false;

	const sph = new THREE.Spherical();
	const target = controls.target;
	const tmp = {
	    distance: controls.getDistance(),
	    phi: controls.getPolarAngle(),
	    theta: controls.getAzimuthalAngle()
	};

	new TWEEN.Tween( tmp )
		.to( { distance: 1, theta: - Math.PI * 0.2 }, 6000 )
		.easing( TWEEN.Easing.Quadratic.Out )
		.onUpdate( function ( n ) {

			sph.set( n.distance, n.phi, n.theta );
			camera.position.setFromSpherical( sph ).add( target );
			camera.lookAt( target );

		} )
		.onComplete( function () {

			controls.enabled = true;
			controls.enableDamping = true;

		} )
		.start();

}

function postProcess( b ) {

	if ( b ) {

		renderer.setEffects( [ taaPass, bloomPass ] );

	} else {

		renderer.setEffects( null );

	}

}

function createGUI() {

	gui = new GUI();
	gui.add( setting, 'roughness', 0, 1, 0.01 ).onChange( upMaterial );
	gui.add( setting, 'metalness', 0, 1, 0.01 ).onChange( upMaterial );
	gui.add( setting, 'opacity', 0, 1, 0.01 ).onChange( upMaterial );

	//

	gui.add( setting, 'postProcess' ).onChange( postProcess );
	gui.add( setting, 'threshold', 0, 1, 0.01 ).onChange( upBloom );
	gui.add( setting, 'strength', 0, 0.1, 0.001 ).onChange( upBloom );
	gui.add( setting, 'radius', 0, 1, 0.01 ).onChange( upBloom );

}

function upMaterial() {

	materials.Gold.metalness = materials.Silver.metalness = setting.metalness;
	materials.Gold.roughness = materials.Silver.roughness = setting.roughness;
	meshes.glass.material.opacity = setting.opacity;

}

function upBloom() {

	if ( ! bloomPass ) return;
	bloomPass.threshold = setting.threshold;
	bloomPass.strength = setting.strength;
	bloomPass.radius = setting.radius;

}

function getTime() {

	const currentDate = new Date();
	let hour = currentDate.getHours();
	const minute = currentDate.getMinutes();
	const second = currentDate.getSeconds();
	let day = currentDate.getDay();
	const month = currentDate.getMonth();
	const milli = currentDate.getMilliseconds();
	if ( hour >= 12 ) hour -= 12;
	if ( day > 30 ) day = 30;

	meshes.hour.rotation.y = - hour * 30 * torad;
	meshes.minute.rotation.y = - minute * 6 * torad;
	meshes.second.rotation.y = - second * 6 * torad;
	meshes.mini_03.rotation.y = - day * 12 * torad;
	meshes.mini_02.rotation.y = - month * 30 * torad;
	meshes.mini_01.rotation.y = - milli * 0.36 * torad;

}

function onWindowResize() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	camera.aspect = width / height;
	camera.updateProjectionMatrix();
	renderer.setSize( width, height );

}

//

function animate() {

	controls.update();

	TWEEN.update();

	renderer.render( scene, camera );

	if ( ready ) getTime();

}

import initJank from 'three/addons/offscreen/jank.js';
import init from 'three/addons/offscreen/scene.js';

// onscreen

const canvas1 = document.getElementById( 'canvas1' );
const canvas2 = document.getElementById( 'canvas2' );

const width = canvas1.clientWidth;
const height = canvas1.clientHeight;
const pixelRatio = window.devicePixelRatio;

init( canvas1, width, height, pixelRatio, './' );
initJank();

// offscreen

const isSafari = /^((?!chrome|android).)*safari/i.test( navigator.userAgent );
let supportOffScreenWebGL = 'transferControlToOffscreen' in canvas2;

// If it's Safari, then check the version because Safari < 17 doesn't support OffscreenCanvas with a WebGL context.
if ( isSafari ) {

	var versionMatch = navigator.userAgent.match( /version\/(\d+)/i );
	var safariVersion = versionMatch ? parseInt( versionMatch[ 1 ] ) : 0;

	supportOffScreenWebGL = safariVersion >= 17;

}

if ( supportOffScreenWebGL ) {

	const offscreen = canvas2.transferControlToOffscreen();
	const worker = new Worker( 'jsm/offscreen/offscreen.js', { type: 'module' } );
	worker.postMessage( {
		drawingSurface: offscreen,
		width: canvas2.clientWidth,
		height: canvas2.clientHeight,
		pixelRatio: window.devicePixelRatio,
		path: '../../'
	}, [ offscreen ] );

} else {

	document.getElementById( 'message' ).style.display = 'block';

}
